INSERT INTO `RoadSigns` VALUES (1,'A','A10','Hmla','a10','Značka Hmla (č. A 10) upozorňuje na úsek vozovky, na ktorom sa dá predpokladať znížená viditeľnosť najmä z dôvodu výskytu hmly, prípadne dymu.');
INSERT INTO `RoadSigns` VALUES (2,'A','A11','Odletujúci štrk','a11','Značka Odletujúci štrk (č. A 11) upozorňuje na miesto alebo úsek vozovky, na ktorom sa dá predpokladať zvýšené riziko odletujúceho štrku spod kolies vozidiel.');
INSERT INTO `RoadSigns` VALUES (3,'A','A12','Svetelné signály','a12','Značka Svetelné signály (č. A 12) upozorňuje na miesto cesty, kde je premávka riadená svetelnými signálmi, ktoré by inak vodič neočakával alebo ktoré nie sú z dostatočnej vzdialenosti viditeľné.');
INSERT INTO `RoadSigns` VALUES (4,'A','A13','Priechod pre chodcov','a13','Značka Priechod pre chodcov (č. A 13) upozorňuje na vyznačený priechod pre chodcov, ktorý by vodič inak neočakával, alebo ktorý nie je z dostatočnej vzdialenosti viditeľný. Značka sa používa najmä mimo obce; v obci vtedy, ak vyznačený priechod pre chodcov je umiestnený mimo križovatky.');
INSERT INTO `RoadSigns` VALUES (5,'A','A14','Pozor, chodci','a14','Značka Chodci (č. A 14) upozorňuje na miesto alebo na úsek cesty, na ktorej je zvýšený pohyb chodcov, napríklad v blízkosti závodov, domovov dôchodcov a podobne.');
INSERT INTO `RoadSigns` VALUES (6,'A','A15','Pozor, deti','a15','Značka Deti (č. A 15) upozorňuje na miesto alebo na úsek cesty, na ktorej je zvýšený pohyb detí a kde sa dá predpokladať zvýšené riziko ich neočakávaného vstupu do vozovky, napríklad v blízkosti školy, detského ihriska a podobne.');
INSERT INTO `RoadSigns` VALUES (7,'A','A16','Pozor, cyklisti','a16','Značka Cyklisti (č. A 16) upozorňuje na miesto, kde cyklisti prechádzajú cez cestu alebo na ňu vchádzajú.');
INSERT INTO `RoadSigns` VALUES (8,'A','A17','Pozor, zvieratá','a17','Značka Zvieratá (č. A 17) upozorňuje na miesto alebo na úsek cesty, na ktorom môže dochádzať k častému výskytu domácich zvierat.');
INSERT INTO `RoadSigns` VALUES (9,'A','A18','Pozor, zver','a18','Značka Zver (č. A 18) upozorňuje na miesto alebo na úsek cesty, na ktorom sa dá predpokladať zvýšené riziko neočakávaného prebiehania voľne žijúcej zveri cez cestu alebo kde vo väčšom množstve tiahnu cez cestu drobné živočíchy, napríklad v lesoch, horských oblastiach, vo zverníkoch a podobne.');
INSERT INTO `RoadSigns` VALUES (10,'A','A19','Práca na ceste','a19','Značka Práca (č. A 19) upozorňuje na prácu na ceste, prípadne na jej súčastiach, ktorá by mohla ohroziť bezpečnosť cestnej premávky alebo pri ktorej by mohli byť ohrození pracovníci, ktorí túto činnosť vykonávajú.');
INSERT INTO `RoadSigns` VALUES (11,'A','A1a','Zákruta vpravo','a1a','Značka Zákruta vpravo (č. A 1a) upozorňuje na smerový oblúk vpravo a značka Zákruta vľavo (č. A 1b) upozorňuje na smerový oblúk vľavo, kde si bezpečný prejazd vyžaduje výrazné zníženie rýchlosti jazdy s ohľadom na parametre cesty, po ktorom nasleduje priamy úsek cesty.');
INSERT INTO `RoadSigns` VALUES (12,'A','A1b','Zákruta vľavo','a1b','Značka Zákruta vpravo (č. A 1a) upozorňuje na smerový oblúk vpravo a značka Zákruta vľavo (č. A 1b) upozorňuje na smerový oblúk vľavo, kde si bezpečný prejazd vyžaduje výrazné zníženie rýchlosti jazdy s ohľadom na parametre cesty, po ktorom nasleduje priamy úsek cesty.');
INSERT INTO `RoadSigns` VALUES (13,'A','A20','Padajúce kamene','a20','Značka Padajúce kamene (č. A 20) upozorňuje na miesto alebo úsek vozovky, na ktorom sa dá predpokladať, že môže dôjsť k zosuvom alebo padaniu kameňov na vozovku.');
INSERT INTO `RoadSigns` VALUES (14,'A','A21','Obojsmerná premávka','a21','Značka Obojsmerná premávka (č. A 21) upozorňuje na úsek cesty, kde je na rozdiel od predchádzajúceho úseku do- časná alebo trvalá premávka v oboch smeroch; na konci takého úseku sa používa značka č. IP 3b. Značka č. A 21 sa používa aj pri skončení smerového rozdelenia cesty a možno ju použiť aj ako predbežnú značku v kombinácii s dodatkovou tabuľkou č. E 2 s uvedením skutočnej vzdialenosti k predmetnému miestu.');
INSERT INTO `RoadSigns` VALUES (15,'A','A22','Pozor, električka','a22','Značka Električka (č. A 22) upozorňuje, ak je to potrebné v záujme bezpečnosti cestnej premávky, na miesto, kde električka križuje smer jazdy ostatných vozidiel.');
INSERT INTO `RoadSigns` VALUES (16,'A','A23','Kolóny','a23','Značka Kolóny (č. A 23) upozorňuje na úsek cesty, kde sa vytvára kolóna vozidiel, resp. rad pohybujúcich sa vozidiel v jednej stope za sebou (v jazdnom pruhu) alebo vedľa seba rovnakým smerom najmä pri veľkej intenzite cestnej premávky, napríklad v dlhých stúpaniach na horských priechodoch alebo ako následok dopravnej nehody alebo práce na ceste a podobne.');
INSERT INTO `RoadSigns` VALUES (17,'A','A24','Tunel','a24','Značka Tunel (č. A 24) vopred upozorňuje na tunel alebo podjazd; ak v záujme bezpečnosti cestnej premávky na tento prejazd platia určité obmedzenia, napríklad výškové, šírkové, alebo zákaz vjazdu pre niektoré druhy vozidiel a podobne, tak sa umiestňujú vopred pred objekt aj príslušné značky alebo príslušné dodatkové tabuľky.');
INSERT INTO `RoadSigns` VALUES (18,'A','A25','Železničné priecestie so závorami','a25','Značka Železničné priecestie so závorami (č. A 25) upozorňuje na miesto, kde je železničné priecestie vybavené mechanickým zabezpečovacím zariadením.');
INSERT INTO `RoadSigns` VALUES (19,'A','A26','Železničné priecestie bez závor','a26','Značka Železničné priecestie bez závor (č. A 26) upozorňuje na miesto, kde je železničné priecestie, ktoré nie je vybavené mechanickým zabezpečovacím zariadením.');
INSERT INTO `RoadSigns` VALUES (20,'A','A27a','Návestná tabuľa ľavá (240 m)','a27a','Značky Návestná tabuľa ľavá – pravá (č. A 27a a č. A 27b – 240 m), (č. A 28a a č. A 28b – 160 m) a (č. A 29a a č. A 29b – 80 m) upozorňujú na železničné priecestie a umiestňujú sa vo vzdialenosti 240 m, 160 m a 80 m pred železničným priecestím. Nad značkou č. A 27a a č. A 27b – 240 m sa umiestňuje značka č. A 25 alebo značka č. A 26. Ak je vzdialenosť medzi dvomi železničnými priecestiami kratšia ako 240 m, je pred nasledujúcim priecestím umiestnená značka č. A 25 alebo značka č. A 26 nad značkou č. A 28a a č. A 28b – 160 m, a ak je táto vzdialenosť kratšia ako 160 m, nad značkou č. A 29a a č. A 29b – 80 m; ak je táto vzdialenosť kratšia ako 80 m, používa sa značka č. A 29a a A 29b – 80 m, nad ktorou je značka č. A 25 alebo značka č. A 26 s dodatkovou tabuľkou č. E 2 udávajúcou vzdialenosť k priecestiu. Ak je vzdialenosť medzi dvomi priecestiami kratšia ako 30 m, je značka pre obe priecestia spoločná; ak ide o železničné priecestia bez závor, je pod značkou č. A 26 umiestnená dodatková tabuľka č. E 1 s nápisom 2x. Na označenie železničného priecestia na odbočujúcu cestu sa používa dodatková tabuľka č. E 7, ktorá je umiestnená nad značkami č. A 27a až A 29b. Ak sa však priecestie nachádza na ceste menšieho dopravného významu, označuje sa len na tejto ceste, a ak je jeho vzdialenosť od križovatky menšia ako 80 m, používa sa aj tu dodatková tabuľka č. E 2 udávajúca vzdialenosť k priecestiu. Na vyznačenie tvaru križovania cesty so železničnou dráhou možno použiť dodatkovú tabuľku č. E 11, ktorá sa umiestňuje nad značkou č. A 29a a č. A 29b – 80 m. Značky č. A 27a až A 29b sa nepoužívajú pred prechodom električkovej dráhy označeným značkou č. P 3.');
INSERT INTO `RoadSigns` VALUES (21,'A','A27b','Návestná tabuľa pravá (240 m)','a27b','Značky Návestná tabuľa ľavá – pravá (č. A 27a a č. A 27b – 240 m), (č. A 28a a č. A 28b – 160 m) a (č. A 29a a č. A 29b – 80 m) upozorňujú na železničné priecestie a umiestňujú sa vo vzdialenosti 240 m, 160 m a 80 m pred železničným priecestím. Nad značkou č. A 27a a č. A 27b – 240 m sa umiestňuje značka č. A 25 alebo značka č. A 26. Ak je vzdialenosť medzi dvomi železničnými priecestiami kratšia ako 240 m, je pred nasledujúcim priecestím umiestnená značka č. A 25 alebo značka č. A 26 nad značkou č. A 28a a č. A 28b – 160 m, a ak je táto vzdialenosť kratšia ako 160 m, nad značkou č. A 29a a č. A 29b – 80 m; ak je táto vzdialenosť kratšia ako 80 m, používa sa značka č. A 29a a A 29b – 80 m, nad ktorou je značka č. A 25 alebo značka č. A 26 s dodatkovou tabuľkou č. E 2 udávajúcou vzdialenosť k priecestiu. Ak je vzdialenosť medzi dvomi priecestiami kratšia ako 30 m, je značka pre obe priecestia spoločná; ak ide o železničné priecestia bez závor, je pod značkou č. A 26 umiestnená dodatková tabuľka č. E 1 s nápisom 2x. Na označenie železničného priecestia na odbočujúcu cestu sa používa dodatková tabuľka č. E 7, ktorá je umiestnená nad značkami č. A 27a až A 29b. Ak sa však priecestie nachádza na ceste menšieho dopravného významu, označuje sa len na tejto ceste, a ak je jeho vzdialenosť od križovatky menšia ako 80 m, používa sa aj tu dodatková tabuľka č. E 2 udávajúca vzdialenosť k priecestiu. Na vyznačenie tvaru križovania cesty so železničnou dráhou možno použiť dodatkovú tabuľku č. E 11, ktorá sa umiestňuje nad značkou č. A 29a a č. A 29b – 80 m. Značky č. A 27a až A 29b sa nepoužívajú pred prechodom električkovej dráhy označeným značkou č. P 3.');
