INSERT INTO `RoadSigns` VALUES (25,'A','A29b','Návestná tabuľa pravá (80 m)','a29b','Značky Návestná tabuľa ľavá – pravá (č. A 27a a č. A 27b – 240 m), (č. A 28a a č. A 28b – 160 m) a (č. A 29a a č. A 29b – 80 m) upozorňujú na železničné priecestie a umiestňujú sa vo vzdialenosti 240 m, 160 m a 80 m pred železničným priecestím. Nad značkou č. A 27a a č. A 27b – 240 m sa umiestňuje značka č. A 25 alebo značka č. A 26. Ak je vzdialenosť medzi dvomi železničnými priecestiami kratšia ako 240 m, je pred nasledujúcim priecestím umiestnená značka č. A 25 alebo značka č. A 26 nad značkou č. A 28a a č. A 28b – 160 m, a ak je táto vzdialenosť kratšia ako 160 m, nad značkou č. A 29a a č. A 29b – 80 m; ak je táto vzdialenosť kratšia ako 80 m, používa sa značka č. A 29a a A 29b – 80 m, nad ktorou je značka č. A 25 alebo značka č. A 26 s dodatkovou tabuľkou č. E 2 udávajúcou vzdialenosť k priecestiu. Ak je vzdialenosť medzi dvomi priecestiami kratšia ako 30 m, je značka pre obe priecestia spoločná; ak ide o železničné priecestia bez závor, je pod značkou č. A 26 umiestnená dodatková tabuľka č. E 1 s nápisom 2x. Na označenie železničného priecestia na odbočujúcu cestu sa používa dodatková tabuľka č. E 7, ktorá je umiestnená nad značkami č. A 27a až A 29b. Ak sa však priecestie nachádza na ceste menšieho dopravného významu, označuje sa len na tejto ceste, a ak je jeho vzdialenosť od križovatky menšia ako 80 m, používa sa aj tu dodatková tabuľka č. E 2 udávajúca vzdialenosť k priecestiu. Na vyznačenie tvaru križovania cesty so železničnou dráhou možno použiť dodatkovú tabuľku č. E 11, ktorá sa umiestňuje nad značkou č. A 29a a č. A 29b – 80 m. Značky č. A 27a až A 29b sa nepoužívajú pred prechodom električkovej dráhy označeným značkou č. P 3.');
INSERT INTO `RoadSigns` VALUES (26,'A','A2a','Dvojitá zákruta, prvá vpravo','a2a','Značka Dvojitá zákruta, prvá vpravo (č. A 2a) upozorňuje na dva protismerné oblúky nasledujúce bezprostredne za sebou, z ktorých prvý je vpravo a druhý vľavo. Značka Dvojitá zákruta, prvá vľavo (č. A 2b) upozorňuje na dva protismerné oblúky, z ktorých prvý je vľavo a druhý vpravo.');
INSERT INTO `RoadSigns` VALUES (27,'A','A2b','Dvojitá zákruta, prvá vľavo','a2b','Značka Dvojitá zákruta, prvá vpravo (č. A 2a) upozorňuje na dva protismerné oblúky nasledujúce bezprostredne za sebou, z ktorých prvý je vpravo a druhý vľavo. Značka Dvojitá zákruta, prvá vľavo (č. A 2b) upozorňuje na dva protismerné oblúky, z ktorých prvý je vľavo a druhý vpravo.');
INSERT INTO `RoadSigns` VALUES (28,'A','A30a','Výstražný kríž pre železničné priecestie jednokoľajové','a30a','Značka Výstražný kríž pre železničné priecestie jednokoľajové (č. A 30a) označuje jednokoľajové železničné priecestie so závorami i bez závor s prejazdovým zabezpečovacím zariadením alebo bez neho a umiestňuje sa tesne pred železničné priecestie.');
INSERT INTO `RoadSigns` VALUES (29,'A','A30b','Výstražný kríž pre železničné priecestie viackoľajové','a30b','Značka Výstražný kríž pre železničné priecestie viackoľajové (č. A 30b) označuje viackoľajové železničné priecestie so závorami i bez závor, s prejazdovým zabezpečovacím zariadením alebo bez neho a umiestňuje sa tesne pred železničné priecestie.');
INSERT INTO `RoadSigns` VALUES (30,'A','A31','Pozor, lietadlá','a31','Značka Lietadlá (č. A 31) upozorňuje na miesto, kde nad cestou v malej výške preletúvajú lietadlá.');
INSERT INTO `RoadSigns` VALUES (31,'A','A32','Bočný vietor','a32','Značka Bočný vietor (č. A 32) upozorňuje na úsek cesty, kde prudký bočný alebo nárazový vietor môže ohroziť bezpečnosť cestnej premávky.');
INSERT INTO `RoadSigns` VALUES (32,'A','A33','Nehoda','a33','Značka Nehoda (č. A 33) upozorňuje na miesto dopravnej nehody a v záujme bezpečnosti cestnej premávky vyzýva k zvýšenej opatrnosti vodičov pri prejazde takto označeným úsekom cesty, ak je vyobrazená na elektronickom alebo elektromechanickom paneli pre premenné značky č. Z 11a alebo č. Z 11b; ak je použitá ako značka v kombinácii s dodatkovou tabuľkou č. E 12, potom vhodným nápisom označuje nehodovú lokalitu s kritickými následkami alebo s ich opakovaným výskytom.');
INSERT INTO `RoadSigns` VALUES (33,'A','A34','Iné nebezpečenstvo','a34','Značka Iné nebezpečenstvo (č. A 34) upozorňuje na iné nebezpečné miesta ako na tie, ktoré možno označiť inou značkou.');
INSERT INTO `RoadSigns` VALUES (34,'A','A3a','Nebezpečné klesanie','a3a','Značka Nebezpečné klesanie (č. A 3a) upozorňuje na miesto, kde klesanie cesty presahuje 10 % alebo kde miestne podmienky robia klesanie nebezpečným, napríklad kde sa nachádza železničné priecestie, križovatka a podobne.');
INSERT INTO `RoadSigns` VALUES (35,'A','A3b','Nebezpečné stúpanie','a3b','Značka Nebezpečné stúpanie (č. A 3b) upozorňuje na miesto, kde stúpanie cesty presahuje 10 % alebo kde miestne podmienky robia stúpanie nebezpečným.');
INSERT INTO `RoadSigns` VALUES (36,'A','A4a','Zúžená vozovka z oboch strán','a4a','Značka Zúžená vozovka z oboch strán (č. A 4a) upozorňuje na miesto, kde sa vozovka zužuje z oboch strán v smere jazdy vodiča, napríklad zúženým miestom môže byť stavebný záber, podjazd, most a podobne.');
INSERT INTO `RoadSigns` VALUES (37,'A','A4b','Zúžená vozovka sprava','a4b','Značky Zúžená vozovka sprava (č. A 4b) a Zúžená vozovka zľava (č. A 4c) upozorňujú na miesto, kde sa vozovka zužuje len z jednej strany v smere jazdy vodiča.');
INSERT INTO `RoadSigns` VALUES (38,'A','A4c','Zúžená vozovka zľava','a4c','Značky Zúžená vozovka sprava (č. A 4b) a Zúžená vozovka zľava (č. A 4c) upozorňujú na miesto, kde sa vozovka zužuje len z jednej strany v smere jazdy vodiča.');
INSERT INTO `RoadSigns` VALUES (39,'A','A5','Nerovnosť vozovky','a5','Značka Nerovnosť vozovky (č. A 5) upozorňuje na priečne alebo pozdĺžne nerovnosti povrchu vozovky, napríklad výtlky, výmole, vyjazdené koľaje a podobne.');
INSERT INTO `RoadSigns` VALUES (40,'A','A6','Spomaľovací prah','a6','Značka Spomaľovací prah (č. A 6) vopred upozorňuje na umelú nerovnosť na povrchu cesty vytvorenú umiestnením spomaľovacieho prahu.');
INSERT INTO `RoadSigns` VALUES (41,'A','A7','Nebezpečná krajnica','a7','Značka Nebezpečná krajnica (č. A 7), ktorej významový symbol môže byť obrátený, upozorňuje na zníženú, nespevnenú alebo inak nebezpečnú krajnicu.');
INSERT INTO `RoadSigns` VALUES (42,'A','A8','Nebezpečenstvo šmyku','a8','Značka Nebezpečenstvo šmyku (č. A 8) upozorňuje na miesto alebo úsek vozovky so zvýšeným rizikom vzniku šmyku vozidla aj na suchej vozovke.');
INSERT INTO `RoadSigns` VALUES (43,'A','A9','Sneh alebo poľadovica','a9','Značka Sneh alebo poľadovica (č. A 9) upozorňuje na úsek vozovky, na ktorom sa nachádza ujazdený a zľadovatený sneh alebo na ktorom hrozí nebezpečenstvo poľadovice.');
INSERT INTO `RoadSigns` VALUES (44,'B','B1','Zákaz vjazdu všetkých vozidiel (v oboch smeroch)','b1','Značka Zákaz vjazdu všetkých vozidiel v oboch smeroch (č. B 1) zakazuje vjazd všetkým druhom vozidiel v oboch smeroch jazdy.');
INSERT INTO `RoadSigns` VALUES (45,'B','B10','Zákaz vjazdu mopedov','b10','Značka Zákaz vjazdu malých motocyklov (č. B 10) zakazuje vjazd malých motocyklov s najväčšou konštrukčnou rýchlosťou 45 km.h-1, ktorých zdvihový objem valcov motora nepresahuje 50 cm3 v prípade spaľovacieho motora a najväčší čistý výkon nie je väčší ako 4 kW alebo ktorých najväčší trvalý menovitý výkon nie je väčší ako 4 kW v prípade elektrického motora z dôvodu ochrany životného prostredia alebo v záujme bezpečnosti cestnej premávky.');
INSERT INTO `RoadSigns` VALUES (46,'B','B11','Zákaz vjazdu bicyklov','b11','Značka Zákaz vjazdu bicyklov (č. B 11) zakazuje vjazd bicyklov; zákaz sa nevzťahuje na prípady, keď je bicykel tlačený.');
INSERT INTO `RoadSigns` VALUES (47,'B','B12','Zákaz vjazdu jazdcov na koňoch','b12','Značka Zákaz vjazdu jazdcov na koňoch (č. B 12) zakazuje vjazd jazdcom na koňoch; zákaz sa vzťahuje aj na prípady, ak je kôň vedený osobou za uzdu alebo za vodidlo.');
INSERT INTO `RoadSigns` VALUES (48,'B','B13','Zákaz vstupu chodcov','b13','Značka Zákaz vstupu chodcov (č. B 13) zakazuje vstup chodcov a používa sa tam, kde je nutné v záujme bezpečnosti cestnej premávky vylúčiť pohyb chodcov, pre ktorých sú spravidla k dispozícii iné trasy.');
INSERT INTO `RoadSigns` VALUES (49,'B','B14','Zákaz vstupu korčuliarov','b14','Značka Zákaz vstupu korčuliarov (č. B 14) zakazuje vstup korčuliarov, skejtbordistov alebo osôb pohybujúcich sa na obdobnom športovom vybavení a používa sa na označenie miest, kde je jazda na korčuliach, skejtbordoch alebo na obdobnom športovom vybavení zakázaná.');
INSERT INTO `RoadSigns` VALUES (50,'B','B15','Zákaz vjazdu záprahových vozidiel','b15','Značka Zákaz vjazdu záprahových vozidiel (č. B 15) zakazuje vjazd záprahových vozidiel a používa sa predovšetkým v prípadoch, keď premávka záprahových vozidiel vzhľadom na ich rýchlosť jazdy a na rozmer by mohla ohroziť bezpečnosť a plynulosť ostatnej cestnej premávky.');
INSERT INTO `RoadSigns` VALUES (51,'B','B16','Zákaz vjazdu ručných vozíkov','b16','Značka Zákaz vjazdu ručných vozíkov (č. B 16) zakazuje vjazd ručným vozíkom s celkovou šírkou väčšou ako 600 mm tam, kde je žiaduce premávku ručných vozíkov vylúčiť vzhľadom na rýchlosť jazdy k ostatnej cestnej premávke a na bezpečnosť osôb, ktoré vozík tlačia alebo ťahajú.');
INSERT INTO `RoadSigns` VALUES (52,'B','B17','Zákaz vjazdu motorových vozidiel s prívesmi','b17','Značka Zákaz vjazdu motorových vozidiel s prívesmi (č. B 17) zakazuje vjazd motorových vozidiel s prívesmi, napríklad s obytnými, nákladnými a podobne.');
INSERT INTO `RoadSigns` VALUES (53,'B','B18','Zákaz vjazdu vyznačených vozidiel','b18','Značka Zákaz vjazdu vyznačených vozidiel (č. B 18) zakazuje vjazd vozidlám vyznačených druhov; tieto druhy vozidiel sa vyznačujú významovými symbolmi zo značiek č. B 4 až B 17 a č. B 21 a č. B 22.');
INSERT INTO `RoadSigns` VALUES (54,'B','B19','Zákaz jazdy motorových vozidiel vo vzdialenosti kratšej ako je vyznačené','b19','Značka Zákaz jazdy motorových vozidiel vo vzdialenosti kratšej, ako je vyznačené (č. B 19), zakazuje vodičovi motorového vozidla jazdu za motorovým vozidlom idúcim pred ním vo vzdialenosti kratšej, ako je vyznačené na značke.');
INSERT INTO `RoadSigns` VALUES (55,'B','B2','Zákaz vjazdu všetkých vozidiel','b2','Značka Zákaz vjazdu všetkých vozidiel (č. B 2) zakazuje vjazd všetkým druhom vozidiel z jedného smeru jazdy. Z opačného smeru sa umiestňuje značka č. IP 3a alebo č. IP 3b.');
INSERT INTO `RoadSigns` VALUES (56,'B','B20','Zákaz vjazdu vozidiel alebo súprav vozidiel, ktorých dĺžka presahuje vyznačenú hranicu','b20','Značka Zákaz vjazdu vozidiel alebo súprav vozidiel, ktorých dĺžka presahuje vyznačenú hranicu (č. B 20), zakazuje vjazd vozidlám alebo súprav vozidiel, ktorých dĺžka vrátane nákladu presahuje vyznačenú hranicu na značke.');
INSERT INTO `RoadSigns` VALUES (57,'B','B21','Zákaz vjazdu vozidiel prepravujúcich nebezpečné veci','b21','Značka Zákaz vjazdu vozidiel prepravujúcich nebezpečné veci (č. B 21) zakazuje vjazd vozidlám prepravujúcim výbušniny, ľahko horľavé alebo inak nebezpečné veci. V prípade zákazu prejazdu týchto vozidiel cez tunel táto značka je doplnená dodatkovou tabuľkou č. E 14.');
INSERT INTO `RoadSigns` VALUES (58,'B','B22','Zákaz vjazdu vozidiel prepravujúcich náklad, ktorý môže spôsobiť znečistenie vody','b22','Značka Zákaz vjazdu vozidiel prepravujúcich náklad, ktorý môže spôsobiť znečistenie vody (č. B 22), zakazuje vjazd týchto vozidiel prepravujúcich náklad, ktorý môže spôsobiť znečistenie vody, napríklad prepravujúcich ropu, ropné materiály alebo iné látky. Množstvo, prípadne druh nákladu možno vyznačiť na príslušnej dodatkovej tabuľke.');
INSERT INTO `RoadSigns` VALUES (59,'B','B23','Zákaz vjazdu vozidiel, ktorých šírka presahuje vyznačenú hranicu','b23','Značka Zákaz vjazdu vozidiel, ktorých šírka presahuje vyznačenú hranicu (č. B 23), zakazuje vjazd vozidlám, ktorých skutočná šírka presahuje vyznačenú hranicu, pričom rozhodujúca je okamžitá šírka vozidla vrátane nákladu.');
INSERT INTO `RoadSigns` VALUES (60,'B','B24','Zákaz vjazdu vozidiel, ktorých výška presahuje vyznačenú hranicu','b24','Značka Zákaz vjazdu vozidiel, ktorých výška presahuje vyznačenú hranicu (č. B 24), zakazuje vjazd vozidlám, ktorých skutočná výška presahuje vyznačenú hranicu, pričom rozhodujúca je okamžitá výška vozidla vrátane nákladu.');
INSERT INTO `RoadSigns` VALUES (61,'B','B25','Zákaz vjazdu vozidiel, ktorých okamžitá hmotnosť presahuje vyznačenú hranicu','b25','Značka Zákaz vjazdu vozidiel, ktorých okamžitá hmotnosť presahuje vyznačenú hranicu (č. B 25), zakazuje vjazd vozidlám, ktorých okamžitá hmotnosť presahuje vyznačenú hranicu na značke, najmä na mostné objekty, ktorých dovolená zaťažiteľnosť neumožňuje vjazd vozidlám, ktorých okamžitá hmotnosť presahuje vyznačenú hranicu povolenú pre bežnú cestnú premávku. Pri jazdnej súprave sa obmedzenie okamžitej hmotnosti vzťahuje na jednotlivé vozidlá súpravy. Ak je značka doplnená dodatkovou tabuľkou s nápisom „Jediné vozidlo ...t“, smie do takto označeného úseku vojsť jediné vozidlo, ktorého okamžitá hmotnosť, ak ide o súpravu, okamžitá hmotnosť všetkých vozidiel súpravy, síce presahuje údaj na značke, nie však údaj na dodatkovej tabuľke; vodič je povinný zabezpečiť, aby na taký úsek nevchádzali súčasne z nijakého smeru iné vozidlá, pričom na tento účel možno zastavovať iné vozidlá. Okamžitá hmotnosť znamená skutočnú hmotnosť vozidla s nákladom, vodičom a s cestujúcimi.');
INSERT INTO `RoadSigns` VALUES (62,'B','B26','Zákaz vjazdu vozidiel, ktorých okamžitá hmotnosť pripadajúca na nápravu presahuje vyznačenú hranicu','b26','Značka Zákaz vjazdu vozidiel, ktorých okamžitá hmotnosť pripadajúca na nápravu presahuje vyznačenú hranicu (č. B 26), zakazuje vjazd vozidlám, ktorých okamžitá hmotnosť pripadajúca na nápravu presahuje vyznačenú hranicu. Značkou sa označujú úseky ciest a mostné objekty, ktorých dovolená zaťažiteľnosť neumožňuje vjazd vozidlám, pri ktorých zaťaženie na ktorúkoľvek nápravu presahuje vyznačenú určenú hranicu. Okamžitá hmotnosť znamená skutočnú hmotnosť vozidla s nákladom, vodičom a s cestujúcimi.');
INSERT INTO `RoadSigns` VALUES (63,'B','B27a','Zákaz odbočovania vpravo','b27a','Značka Zákaz odbočovania vpravo (č. B 27a) zakazuje odbočovanie vpravo a značka Zákaz odbočovania vľavo (č. B 27b) zakazuje odbočovanie vľavo napríklad na križovatke, na miesto mimo cesty, na poľnú cestu, lesnú cestu, cestičku pre cyklistov, do obytnej zóny alebo do pešej zóny.');
INSERT INTO `RoadSigns` VALUES (64,'B','B27b','Zákaz odbočovania vľavo','b27b','Značka Zákaz odbočovania vpravo (č. B 27a) zakazuje odbočovanie vpravo a značka Zákaz odbočovania vľavo (č. B 27b) zakazuje odbočovanie vľavo napríklad na križovatke, na miesto mimo cesty, na poľnú cestu, lesnú cestu, cestičku pre cyklistov, do obytnej zóny alebo do pešej zóny.');
INSERT INTO `RoadSigns` VALUES (65,'B','B28','Zákaz otáčania','b28','Značka Zákaz otáčania (č. B 28) zakazuje otáčanie vozidiel najmä v prípadoch, v ktorých môže otáčanie ohrozovať bezpečnosť a plynulosť cestnej premávky. Značka Zákaz predchádzania (č. B 29a) zakazuje vodičovi predchádzať motorové vozidlo vľavo; motocykel bez postranného vozíka možno predchádzať.');
INSERT INTO `RoadSigns` VALUES (66,'B','B29a','Zákaz predchádzania','b29a','Značka Zákaz predchádzania (č. B 29a) zakazuje vodičovi predchádzať motorové vozidlo vľavo; motocykel bez postranného vozíka možno predchádzať.');
INSERT INTO `RoadSigns` VALUES (67,'B','B29b','Koniec zákazu predchádzania','b29b','Značka Koniec zákazu predchádzania (č. B 29b) končí platnosť obmedzenia vyznačeného značkou č. B 29a, ak nie je skôr skončené inak.');
INSERT INTO `RoadSigns` VALUES (68,'B','B3','Zákaz vjazdu všetkých motorových vozidiel','b3','Značka Zákaz vjazdu všetkých motorových vozidiel (č. B 3) zakazuje vjazd všetkým motorovým vozidlám, ale nezakazuje vjazd električke.');
INSERT INTO `RoadSigns` VALUES (69,'B','B30a','Zákaz predchádzania pre nákladné automobily','b30a','Značka Zákaz predchádzania pre nákladné automobily (č. B 30a) zakazuje vodičovi nákladného automobilu s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg predchádzať motorové vozidlo vľavo; motocykel bez postranného vozíka možno predchádzať.');
INSERT INTO `RoadSigns` VALUES (70,'B','B30b','Koniec zákazu predchádzania pre nákladné automobily','b30b','Značka Koniec zákazu predchádzania pre nákladné automobily (č. B 30b) končí platnosť obmedzenia vyznačeného značkou č. B 30a, ak nie je skôr skončené inak.');
INSERT INTO `RoadSigns` VALUES (71,'B','B31a','Najvyššia dovolená rýchlosť','b31a','Značka Najvyššia dovolená rýchlosť (č. B 31a) zakazuje vodičovi prekročiť rýchlosť v kilometroch za hodinu vyznačenú číslom na značke; značka končí platnosť predchádzajúcej značky č. B 31a s iným údajom na značke, ak nie je skôr skončená inak.');
INSERT INTO `RoadSigns` VALUES (72,'B','B31b','Koniec najvyššej dovolenej rýchlosti','b31b','Značka Koniec najvyššej dovolenej rýchlosti (č. B 31b) končí platnosť obmedzenia vyznačeného značkou č. B 31a, ak nie je skôr skončené inak. Na značke č. B 31b sa v takom prípade použije zhodný významový symbol z použitej značky č. B 31a.');
INSERT INTO `RoadSigns` VALUES (73,'B','B32a','Zákaz zvukových výstražných zariadení','b32a','Značka Zákaz zvukových výstražných znamení (č. B 32a) zakazuje vodičovi používať zvukové výstražné znamenia a osadzuje sa najmä na cestách, ktoré vedú v blízkosti zdravotníckych, kúpeľných a podobných zariadení.');
INSERT INTO `RoadSigns` VALUES (74,'B','B32b','Koniec zákazu zvukových výstražných zariadení','b32b','Značka Koniec zákazu zvukových výstražných znamení (č. B 32b) končí platnosť obmedzenia vyznačeného značkou č. B 32a, ak nie je skôr skončené inak.');
INSERT INTO `RoadSigns` VALUES (75,'B','B33','Zákaz státia','b33','Značka Zákaz státia (č. B 33) sa používa najmä v prípadoch, keď je nutné v záujme bezpečnosti a plynulosti cestnej premávky a s prihliadnutím na miestne podmienky zakázať státie vozidiel a umožniť iba ich zastavenie napríklad najmä na účel zásobovania.');
INSERT INTO `RoadSigns` VALUES (76,'B','B34','Zákaz zastavenia','b34','Značka Zákaz zastavenia (č. B 34) sa používa v prípade, keď by zastavenie vozidla mohlo s prihliadnutím na dané dopravné podmienky výrazne ohroziť bezpečnosť cestnej premávky alebo narušiť jej plynulosť.');
INSERT INTO `RoadSigns` VALUES (77,'B','B35','Zákaz státia v nepárnych dňoch','b35','Značka Zákaz státia v nepárnych dňoch (č. B 35) zakazuje státie v nepárnych kalendárnych dňoch v mesiaci.');
INSERT INTO `RoadSigns` VALUES (78,'B','B36','Zákaz státia v párnych dňoch','b36','Značka Zákaz státia v párnych dňoch (č. B 36) zakazuje státie v párnych kalendárnych dňoch v mesiaci.');
INSERT INTO `RoadSigns` VALUES (79,'B','B37','Iný zákaz','b37','Značka Iný zákaz (č. B 37) určuje iný zákaz ako ten, ktorý možno vyznačiť inou zákazovou značkou. Zákaz je vyjadrený príslušným stručným nápisom vnútri tejto značky, napríklad „PREJAZD ZAKÁZANÝ“, „NAKLADANIE A SKLADANIE TOVARU ZAKÁZANÉ“, alebo ak sa použije nápis „PREJAZD ZAKÁZANÝ“, nesmie vodič prejsť takto označeným úsekom bez toho, aby jazdu prerušil napríklad s cieľom naložiť alebo zložiť náklad a podobne. Ak sa v záujme bezpečnosti premávky použije nápis „LPG“, „CNG“ alebo „LNG“, je tým vyjadrený zákaz vjazdu vozidiel, ktoré vo svojom pohonnom systéme využívajú skvapalnený ropný plyn LPG, stlačený zemný plyn CNG alebo skvapalnený zemný plyn LNG, najmä do miest, kde by pri úniku LPG, CNG alebo LNG mohlo dôjsť k ich vznieteniu. Ak sa v záujme ochrany životného prostredia použije nápis „EURO X“, pričom za „X“ sa podľa potreby dosadí vhodné číslo, je tým vyjadrený zákaz vjazdu vozidiel, ktoré nespĺňajú emisné limity „EURO X“ a nižšie.');
INSERT INTO `RoadSigns` VALUES (80,'B','B38','Povinnosť zastaviť vozidlo','b38','Značka Povinnosť zastaviť vozidlo (č. B 38) zakazuje pokračovať v jazde bez zastavenia vozidla na cestnom hraničnom priechode. V spodnej časti tejto značky sa uvádza preklad nápisu CLO v jazyku susedného štátu. Ak je namiesto nápisu CLO nápis STOP, značka zakazuje pokračovať v jazde bez zastavenia vozidla na mieste uvedenom v spodnej časti značky, napríklad POLÍCIA, KONTROLA a podobne.');
INSERT INTO `RoadSigns` VALUES (81,'B','B39','Koniec viacerých zákazov','b39','Značka Koniec viacerých zákazov (č. B 39) končí platnosť značiek č. B 29a, č. B 30a, č. B 31a a č. C 15, ak nie je skôr skončená inak; ak sú použité najmenej dve z týchto značiek spoločne, umiestňuje sa na konci platnosti obmedzení vyplývajúcich zo spoločného použitia značiek.');
INSERT INTO `RoadSigns` VALUES (82,'B','B4','Zákaz vjazdu všetkých motorových vozidiel s výnimkou motocyklov bez postranného vozíka','b4','Značka Zákaz vjazdu všetkých motorových vozidiel s výnimkou motocyklov bez postranného vozíka (č. B 4) zakazuje vjazd všetkých motorových vozidiel s výnimkou motocyklov bez postranného vozíka, ale nezakazuje vjazd električke.');
INSERT INTO `RoadSigns` VALUES (83,'B','B5','Zákaz vjazdu osobných automobilov','b5','Značka Zákaz vjazdu osobných automobilov (č. B 5) zakazuje vjazd osobným automobilom.');
INSERT INTO `RoadSigns` VALUES (84,'B','B6','Zákaz vjazdu nákladných automobilov','b6','Značka Zákaz vjazdu nákladných automobilov (č. B 6) zakazuje okrem vjazdu nákladných automobilov aj vjazd ťahača prívesu, ťahača návesu a špeciálnych automobilov odvodených od nákladného automobilu alebo od autobusu; nezakazuje vjazd obytným automobilom a nákladným automobilom s najväčšou prípustnou celkovou hmotnosťou neprevyšujúcou 3 500 kg.');
INSERT INTO `RoadSigns` VALUES (85,'B','B7','Zákaz vjazdu autobusov','b7','Značka Zákaz vjazdu autobusov (č. B 7) v záujme bezpečnosti cestnej premávky zakazuje vjazd autobusov na cesty, ktoré svojimi parametrami, napríklad šírkou alebo smerovými oblúkmi cesty, neumožňujú bezpečnú jazdu autobusov s prihliadnutím na ich rozmery, resp. na najväčšiu prípustnú celkovú hmotnosť. Značka č. B 7 sa používa i v prípadoch, keď je potrebné premávku autobusov vylúčiť z dôvodu ochrany životného prostredia.');
INSERT INTO `RoadSigns` VALUES (86,'B','B8','Zákaz vjazdu motocyklov','b8','Značka Zákaz vjazdu motocyklov (č. B 8) zakazuje vjazd motocyklov, ktorých najväčšia konštrukčná rýchlosť je viac ako 45 km.h-1 alebo ktorých zdvihový objem valcov motora je väčší ako 50 cm3 v prípade spaľovacieho motora a najväčší čistý výkon je väčší ako 4 kW alebo ktorých najväčší trvalý menovitý výkon je väčší ako 4 kW v prípade elektrického motora z dôvodu ochrany životného prostredia alebo v záujme bezpečnosti cestnej premávky.');
INSERT INTO `RoadSigns` VALUES (87,'B','B9','Zákaz vjazdu traktorov','b9','Značka Zákaz vjazdu traktorov (č. B 9) zakazuje vjazd traktorom a všetkým zvláštnym motorovým vozidlám, ako sú napríklad jednonápravové kultivačné traktory, motorové dopravné vozíky, motorové ručné vozíky, samohybné poľnohospodárske a lesné stroje a pojazdné pracovné stroje.');
INSERT INTO `RoadSigns` VALUES (88,'C','C1','Prikázaný smer jazdy priamo','c1','Značky Prikázaný smer jazdy (č. C 1 až C 4c) a značka Prikázaný smer otáčania (č. C 5) prikazujú smer jazdy len v smere, ktorým šípka alebo šípky vyobrazené na príslušnej značke ukazujú, čím je zároveň vyjadrený zákaz jazdy iným smerom. Značky č. C 1 až C 4c a značka Prikázaný smer otáčania č. C 5 sa používajú najmä pred križovatkou.');
INSERT INTO `RoadSigns` VALUES (89,'C','C10','Cestička pre korčuliarov','c10','Značka Cestička pre korčuliarov (č. C 10) prikazuje korčuliarom, skejtbordistom alebo osobám pohybujúcim sa na obdobnom športovom vybavení použiť v predmetnom smere takto označenú cestičku alebo pruh. Cestičku alebo pruh pre korčuliarov môže použiť cyklista alebo osoba tlačiaca bicykel alebo pohybujúca sa na lyžiach alebo na obdobnom športovom vybavení, ak tým neobmedzí ani neohrozí korčuliarov. Iným účastníkom cestnej premávky je používanie cestičky alebo pruhu zakázané.');
INSERT INTO `RoadSigns` VALUES (90,'C','C11','Cestička pre jazdcov na koňoch','c11','Značka Cestička pre jazdcov na koňoch (č. C 11) prikazuje jazdcom na koňoch použiť v predmetnom smere takto označenú cestičku alebo pruh. Iným účastníkom cestnej premávky je používanie cestičky alebo pruhu zakázané; zákaz sa nevzťahuje na osoby vedúce koňa za uzdu alebo vodidlo.');
INSERT INTO `RoadSigns` VALUES (91,'C','C12','Cestička pre vyznačených užívateľov','c12','Značka Cestička pre vyznačených užívateľov (č. C 12) prikazuje vyobrazeným významovým symbolom vyznačeným užívateľom, napríklad chodcom a cyklistom, použiť v predmetnom smere takto označenú spoločnú cestičku alebo pruh. Cyklista pritom nesmie ohroziť chodca. Cestičku alebo pruh môže použiť aj osoba pohybujúca sa na kolieskových korčuliach, lyžiach alebo na obdobnom športovom vybavení, ak tým neobmedzí ani neohrozí vyznačených užívateľov. Iným účastníkom cestnej premávky je používanie cestičky alebo pruhu zakázané.');
INSERT INTO `RoadSigns` VALUES (92,'C','C13','Cestička pre vyznačených užívateľov','c13','Značka Cestička pre vyznačených užívateľov (č. C 13) prikazuje vyobrazeným významovým symbolom vyznačeným užívateľom použiť v predmetnom smere takto označenú cestičku alebo pruh, ale iba vyznačeným spôsobom, t. j. vyznačení užívatelia sú povinní použiť len pruh pre nich určený; to neplatí pri obchádzaní, predchádzaní, odbočovaní, otáčaní, pri vchádzaní na cestičku a vychádzaní z nej, pričom sa nesmú navzájom ohroziť. Iným účastníkom cestnej premávky je používanie cestičky alebo pruhu zakázané.');
INSERT INTO `RoadSigns` VALUES (93,'C','C14','Použiť protisklzové reťaze','c14','Značka Použiť protisklzové reťaze (č. C 14) prikazuje vodičom na takto označenom úseku cesty použiť pri jazde protisklzové reťaze. Reťaze sa musia použiť minimálne na dvoch kolesách hnacej nápravy.');
INSERT INTO `RoadSigns` VALUES (94,'C','C15','Najnižšia dovolená rýchlosť','c15','Značka Najnižšia dovolená rýchlosť (č. C 15) sa používa v záujme zvýšenia plynulosti cestnej premávky.');
INSERT INTO `RoadSigns` VALUES (95,'C','C16','Iný príkaz','c16','Značka Iný príkaz (č. C 16) ukladá iný príkaz ako ten, ktorý možno uložiť inou značkou. Príkaz je vyznačený vhodným nápisom, ako napríklad „PREJDITE NA DRUHÚ STRANU“, alebo vyobrazením príslušného významového symbolu napríklad zo značky č. B 7 a podobne. Značkou č. C 16 je možné ukladať aj príkazy jednotlivým skupinám účastníkov cestnej premávky, napríklad vodičom „POUŽI ZAKLADACIE KLINY“ a podobne alebo chodcom „POUŽI PODCHOD“ a podobne.');
INSERT INTO `RoadSigns` VALUES (96,'C','C17','Rozsvieť svetlá','c17','Značka Rozsvieť svetlá (č. C 17) prikazuje vodičovi na takto označenom úseku rozsvietiť na idúcom vozidle ustanovené osvetlenie; skončením platnosti príkazu značky č. C 17 nie je dotknutá povinnosť používať ustanovené osvetlenie vyplývajúce zo všeobecnej úpravy pravidiel cestnej premávky.');
INSERT INTO `RoadSigns` VALUES (97,'C','C18','Koniec príkazu','c18','Značka Koniec príkazu (č. C 18) končí platnosť značiek č. C 8, č. C 9, č. C 10, č. C 11, č. C 12, č. C 13, č. C 14, č. C 15, č. C 16, č. C 17, ak nie je skôr skončená inak. Na značke sa použije zhodný symbol z týchto značiek doplnený červeným šikmým pruhom.');
INSERT INTO `RoadSigns` VALUES (98,'C','C19','Prikázaný smer prepravy vyznačených vozidiel a vecí','c19','Značka Prikázaný smer prepravy vyznačených vozidiel a vecí (č. C 19) prikazuje vodičom vozidiel prepravujúcim výbušniny, ľahko horľavé alebo inak nebezpečné veci alebo len vodičom vyznačených druhov vozidiel jazdu len smerom, ktorý ukazuje šípka alebo šípky vyznačené na značke. V prípade použitia značky č. C 19 v kombinácii s dodatkovou tabuľkou č. E 14 prikazuje vodičom týchto vozidiel, ktoré obmedzuje dodatková tabuľka č. E 14, jazdu len tým smerom, ktorý ukazuje šípka alebo šípky vyznačené na značke. Na značke možno na určenie iného druhu vozidla použiť významový symbol značky zo značiek č. B 4 až B 9 a č. B 17 až B 26 a na prikázanie smeru jazdy symbol značky zo značiek č. C 1 až C 5.');
INSERT INTO `RoadSigns` VALUES (99,'C','C2','Prikázaný smer jazdy vpravo','c2','Značky Prikázaný smer jazdy (č. C 1 až C 4c) a značka Prikázaný smer otáčania (č. C 5) prikazujú smer jazdy len v smere, ktorým šípka alebo šípky vyobrazené na príslušnej značke ukazujú, čím je zároveň vyjadrený zákaz jazdy iným smerom. Značky č. C 1 až C 4c a značka Prikázaný smer otáčania č. C 5 sa používajú najmä pred križovatkou.');
INSERT INTO `RoadSigns` VALUES (100,'C','C20','Usporiadanie jazdných pruhov','c20','Značka Usporiadanie jazdných pruhov (č. C 20) označuje počet a usporiadanie jazdných pruhov v smere jazdy v nasledujúcom úseku cesty. V prípade potreby je možné na značke vyznačiť aj počet a usporiadanie jazdných pruhov v protismere jazdy. Značka sa umiestňuje v mieste, kde sa úprava počtu a usporiadanie jazdných pruhov začína.');
INSERT INTO `RoadSigns` VALUES (101,'C','C21','Usporiadanie jazdných pruhov','c21','Značka Usporiadanie jazdných pruhov (č. C 21) označuje počet a usporiadanie jazdných pruhov v smere jazdy a zároveň označuje, ktorý z jazdných pruhov je priebežný; zodpovedá skutočnej dopravnej situácii na ceste.');
INSERT INTO `RoadSigns` VALUES (102,'C','C22a','Zvýšenie počtu jazdných pruhov','c22a','Značka Zvýšenie počtu jazdných pruhov (č. C 22a) označuje úsek cesty, kde dochádza, oproti predchádzajúcemu úseku, k zvýšeniu počtu jazdných pruhov v smere jazdy, a zároveň označuje, ktorý z jazdných pruhov je priebežný, a to najmä mimo obce. Značka sa vždy umiestňuje na začiatku rozširovacieho klina a zodpovedá skutočnej dopravnej situácii na ceste, počtu a usporiadaniu jazdných pruhov.');
INSERT INTO `RoadSigns` VALUES (103,'C','C22b','Zníženie počtu jazdných pruhov','c22b','Značka Zníženie počtu jazdných pruhov (č. C 22b) označuje úsek cesty, kde dochádza, oproti predchádzajúcemu úseku, k zníženiu počtu jazdných pruhov v smere jazdy, a zároveň označuje, ktorý z jazdných pruhov je priebežný, ako aj jazdný pruh určený na zaraďovanie do priebežného pruhu. Značka sa používa aj na označenie konca samostatného jazdného pruhu pre pomalé vozidlá. Zhotovenie značky zodpovedá skutočnej dopravnej situácii na ceste, počtu a usporiadaniu jazdných pruhov a umiestňuje sa na začiatku výjazdového klina.');
INSERT INTO `RoadSigns` VALUES (104,'C','C22c','Zvýšenie počtu jazdných pruhov pre pomalé vozidlá','c22c','Značka Zvýšenie počtu jazdných pruhov pre pomalé vozidlá (č. C 22c) označuje v smere jazdy prídavný jazdný pruh určený pre vozidlá, ktoré svojou pomalou jazdou obmedzujú alebo by mohli obmedziť ostatné vozidlá. Značka sa vždy umiestňuje na začiatku rozširovacieho klina a zodpovedá skutočnej dopravnej situácii na ceste, počtu a usporiadaniu jazdných pruhov.');
INSERT INTO `RoadSigns` VALUES (105,'C','C23a','Obmedzenie v jazdných pruhoch','c23a','Značky Obmedzenie v jazdných pruhoch (č. C 23a a č. C 23b) vyznačujú obmedzenie platné v príslušnom jazdnom pruhu v smere jazdy s použitím symbolu značky z príslušnej skupiny zákazových alebo príkazových značiek. Vyjadrenie počtu a usporiadania jazdných pruhov na značke č. C 23a a č. C 23b zodpovedá skutočnej dopravnej situácii na ceste. Zákaz alebo obmedzenie, ktoré sa týka odbočujúcej cesty, možno vyznačiť obmedzením v príslušnom jazdnom pruhu pre zaraďovanie pred križovatkou. V prípade, že obmedzenie v jazdnom pruhu pokračuje aj za križovatkou, je potrebné príslušnú značku zopakovať. Značky č. C 23a a č. C 23b sa umiestňujú v mieste, kde sa obmedzenie v jazdnom pruhu začína. Ak sa úsek platnosti obmedzenia končí mimo križovatky a ak nie je skôr skončený inak, platnosť obmedzenia v jazdných pruhoch sa končí umiestnením príslušnej značky, ktorá vyjadruje počet a usporiadanie jazdných pruhov zodpovedajúce skutočnej dopravnej situácii na ceste, počtu a usporiadaniu jazdných pruhov a ktorá už neobsahuje symbol zákazovej alebo príkazovej značky.');
INSERT INTO `RoadSigns` VALUES (106,'C','C23b','Obmedzenie v jazdných pruhoch','c23b','Značky Obmedzenie v jazdných pruhoch (č. C 23a a č. C 23b) vyznačujú obmedzenie platné v príslušnom jazdnom pruhu v smere jazdy s použitím symbolu značky z príslušnej skupiny zákazových alebo príkazových značiek. Vyjadrenie počtu a usporiadania jazdných pruhov na značke č. C 23a a č. C 23b zodpovedá skutočnej dopravnej situácii na ceste. Zákaz alebo obmedzenie, ktoré sa týka odbočujúcej cesty, možno vyznačiť obmedzením v príslušnom jazdnom pruhu pre zaraďovanie pred križovatkou. V prípade, že obmedzenie v jazdnom pruhu pokračuje aj za križovatkou, je potrebné príslušnú značku zopakovať. Značky č. C 23a a č. C 23b sa umiestňujú v mieste, kde sa obmedzenie v jazdnom pruhu začína. Ak sa úsek platnosti obmedzenia končí mimo križovatky a ak nie je skôr skončený inak, platnosť obmedzenia v jazdných pruhoch sa končí umiestnením príslušnej značky, ktorá vyjadruje počet a usporiadanie jazdných pruhov zodpovedajúce skutočnej dopravnej situácii na ceste, počtu a usporiadaniu jazdných pruhov a ktorá už neobsahuje symbol zákazovej alebo príkazovej značky.');
INSERT INTO `RoadSigns` VALUES (107,'C','C24a','Vyhradený jazdný pruh','c24a','Značka Vyhradený jazdný pruh (č. C 24a) označuje jazdný pruh vyhradený napríklad pre vozidlá pravidelnej verejnej dopravy, ako sú autobusy alebo trolejbusy, a jeho situovanie vo vzťahu k ostatným jazdným pruhom; vyhradený jazdný pruh pre vozidlá pravidelnej verejnej dopravy môžu používať okrem vozidiel pravidelnej verejnej dopravy aj vozidlá taxislužby zriadené na prepravu osôb. Značka č. C 24a sa používa najmä so značkami č. V 1a, č. V 2a alebo so značkou č. V 14 s príslušným nápisom na ceste (BUS). V priestore križovatky sa vyhradený jazdný pruh označuje iba príslušnými vodorovnými značkami. Ak vyhradený jazdný pruh je vyhradený len na určitý čas, tento čas sa uvádza v spodnej časti značky č. C 24a.');
INSERT INTO `RoadSigns` VALUES (108,'C','C24b','Koniec vyhradeného jazdného pruhu','c24b','Značka Koniec vyhradeného jazdného pruhu (č. C 24b) označuje skončenie platnosti značky č. C 24a a použije sa, ak sa platnosť značky končí mimo križovatky a ak nie je skôr skončená inak.');
INSERT INTO `RoadSigns` VALUES (109,'C','C25','Radenie jazdných pruhov pred križovatkou','c25','Značka Radenie jazdných pruhov pred križovatkou (č. C 25) označuje spôsob radenia do jazdných pruhov a určený smer jazdy cez križovatku v súlade s príslušnými vodorovnými značkami a zodpovedá skutočnej dopravnej situácii na ceste; značkou možno vyznačiť, kde platí povolené otáčanie vozidiel v priestore riadenej križovatky. V prípade potreby možno značku doplniť príslušným symbolom značky zo skupiny zákazových alebo príkazových značiek.');
INSERT INTO `RoadSigns` VALUES (110,'C','C26','Zmena smeru jazdy','c26','Značka Zmena smeru jazdy (č. C 26) vopred informuje o zmene smeru jazdy do protismeru na smerovo rozdelenej ceste alebo do pôvodného smeru jazdy, ak je symbol šípky na značke obrátený. Na značke je vyznačená skutočná zmena smeru jazdy, počet jazdných pruhov a vzdialenosť k miestu zmeny smeru jazdy.');
INSERT INTO `RoadSigns` VALUES (111,'C','C27','Obchádzanie električky','c27','Značka Obchádzanie električky (č. C 27) označuje miesto, kde možno vľavo obchádzať električku, ktorá stojí na zastávke. Ak je značka doplnená v spodnej časti symbolom dodatkovej tabuľky č. E 4, vyznačuje úsek cesty, kde je povolená jazda pozdĺž električky vľavo.');
INSERT INTO `RoadSigns` VALUES (112,'C','C28','Zmena smeru jazdy','c28','Značky Zmena smeru jazdy (č. C 28 a č. C 29) upozorňujú na neočakávanú zmenu smeru jazdy. Značka č. C 29 upozorňuje na zmenu smeru jazdy pred trvalou prekážkou na ceste. Na značkách č. C 28 a č. C 29 je vyznačená skutočná zmena smeru jazdy a počet jazdných pruhov. V spodnej časti značky č. C 28 a č. C 29 alebo na dodatkovej tabuľke možno uviesť ďalšie doplňujúce údaje napríklad o vzdialenosti k miestu zmeny smeru jazdy a podobne.');
INSERT INTO `RoadSigns` VALUES (113,'C','C29','Zmena smeru jazdy','c29','Značky Zmena smeru jazdy (č. C 28 a č. C 29) upozorňujú na neočakávanú zmenu smeru jazdy. Značka č. C 29 upozorňuje na zmenu smeru jazdy pred trvalou prekážkou na ceste. Na značkách č. C 28 a č. C 29 je vyznačená skutočná zmena smeru jazdy a počet jazdných pruhov. V spodnej časti značky č. C 28 a č. C 29 alebo na dodatkovej tabuľke možno uviesť ďalšie doplňujúce údaje napríklad o vzdialenosti k miestu zmeny smeru jazdy a podobne.');
INSERT INTO `RoadSigns` VALUES (114,'C','C3','Prikázaný smer jazdy vľavo','c3','Značky Prikázaný smer jazdy (č. C 1 až C 4c) a značka Prikázaný smer otáčania (č. C 5) prikazujú smer jazdy len v smere, ktorým šípka alebo šípky vyobrazené na príslušnej značke ukazujú, čím je zároveň vyjadrený zákaz jazdy iným smerom. Značky č. C 1 až C 4c a značka Prikázaný smer otáčania č. C 5 sa používajú najmä pred križovatkou.');
INSERT INTO `RoadSigns` VALUES (115,'C','C30','Striedavé radenie','c30','Značka Striedavé radenie (č. C 30), ktorej symbol môže byť obrátený, vyznačuje miesto, kde platí striedavé radenie do priebežného jazdného pruhu. Značka sa používa v záujme zvýšenia plynulosti cestnej premávky, ak je pri súbežnej jazde v niektorom jazdnom pruhu prekážka cestnej premávky. Vodič vozidla idúceho vo voľnom alebo v priebežnom jazdnom pruhu je povinný umožniť vodičovi prvého vozidla nachádzajúceho sa v jazdnom pruhu, v ktorom je prekážka, ak ten dáva znamenie o zmene smeru jazdy, preradenie do voľného alebo priebežného jazdného pruhu. Vodič pri zaraďovaní do voľného alebo priebežného jazdného pruhu pritom nesmie ohroziť vodiča jazdiaceho vo voľnom alebo priebežnom jazdnom pruhu.');
INSERT INTO `RoadSigns` VALUES (116,'C','C4a','Prikázaný smer jazdy vpravo a vľavo','c4a','Značky Prikázaný smer jazdy (č. C 1 až C 4c) a značka Prikázaný smer otáčania (č. C 5) prikazujú smer jazdy len v smere, ktorým šípka alebo šípky vyobrazené na príslušnej značke ukazujú, čím je zároveň vyjadrený zákaz jazdy iným smerom. Značky č. C 1 až C 4c a značka Prikázaný smer otáčania č. C 5 sa používajú najmä pred križovatkou.');
INSERT INTO `RoadSigns` VALUES (117,'C','C4b','Prikázaný smer jazdy priamo a vpravo','c4b','Značky Prikázaný smer jazdy (č. C 1 až C 4c) a značka Prikázaný smer otáčania (č. C 5) prikazujú smer jazdy len v smere, ktorým šípka alebo šípky vyobrazené na príslušnej značke ukazujú, čím je zároveň vyjadrený zákaz jazdy iným smerom. Značky č. C 1 až C 4c a značka Prikázaný smer otáčania č. C 5 sa používajú najmä pred križovatkou.');
INSERT INTO `RoadSigns` VALUES (118,'C','C4c','Prikázaný smer jazdy priamo a vľavo','c4c','Značky Prikázaný smer jazdy (č. C 1 až C 4c) a značka Prikázaný smer otáčania (č. C 5) prikazujú smer jazdy len v smere, ktorým šípka alebo šípky vyobrazené na príslušnej značke ukazujú, čím je zároveň vyjadrený zákaz jazdy iným smerom. Značky č. C 1 až C 4c a značka Prikázaný smer otáčania č. C 5 sa používajú najmä pred križovatkou.');
INSERT INTO `RoadSigns` VALUES (119,'C','C5','Prikázaný smer otáčania','c5','Značky Prikázaný smer jazdy (č. C 1 až C 4c) a značka Prikázaný smer otáčania (č. C 5) prikazujú smer jazdy len v smere, ktorým šípka alebo šípky vyobrazené na príslušnej značke ukazujú, čím je zároveň vyjadrený zákaz jazdy iným smerom. Značky č. C 1 až C 4c a značka Prikázaný smer otáčania č. C 5 sa používajú najmä pred križovatkou.');
INSERT INTO `RoadSigns` VALUES (120,'C','C6a','Prikázaný smer obchádzania vpravo','c6a','Značka Prikázaný smer obchádzania vpravo (č. C 6a) prikazuje obchádzať ostrovček, prekážku a podobne len v smere vyznačenom šípkou na značke.');
INSERT INTO `RoadSigns` VALUES (121,'C','C6b','Prikázaný smer obchádzania vľavo','c6b','Značka Prikázaný smer obchádzania vľavo (č. C 6b) prikazuje obchádzať ostrovček, prekážku a podobne len v smere vyznačenom šípkou na značke.');
INSERT INTO `RoadSigns` VALUES (122,'C','C6c','Prikázaný smer obchádzania vpravo a vľavo','c6c','Značka Prikázaný smer obchádzania vpravo alebo vľavo (č. C 6c) prikazuje obchádzať ostrovček, prekážku a podobne len v smere vyznačenom šípkami na značke.');
INSERT INTO `RoadSigns` VALUES (123,'C','C7','Kruhový objazd','c7','Značka Kruhový objazd (č. C 7) označuje kruhový objazd a prikazuje smer jazdy len v smere vyznačených šípok na značke. Vodič vchádzajúci do kruhového objazdu má prednosť v jazde, ak nie je prednosť v jazde upravená značkami.');
INSERT INTO `RoadSigns` VALUES (124,'C','C8','Cestička pre cyklistov','c8','Značka Cestička pre cyklistov (č. C 8) prikazuje cyklistom použiť v predmetnom smere takto označenú cestičku alebo pruh. Cestičku alebo pruh pre cyklistov môže použiť aj osoba pohybujúca sa na kolieskových korčuliach, lyžiach alebo na obdobnom športovom vybavení, ak tým neobmedzí ani neohrozí cyklistov; cestičku alebo pruh smie použiť aj osoba tlačiaca bicykel. Iným účastníkom cestnej premávky je používanie cestičky alebo pruhu zakázané.');
INSERT INTO `RoadSigns` VALUES (125,'C','C9','Cestička pre chodcov','c9','Značka Cestička pre chodcov (č. C 9) prikazuje chodcom použiť v predmetnom smere takto označenú cestičku alebo pruh. Iným účastníkom cestnej premávky je používanie cestičky alebo pruhu zakázané.');
INSERT INTO `RoadSigns` VALUES (126,'E','E1','Počet','e1','Dodatková tabuľka Počet (č. E 1) sa umiestňuje pod príslušné značky, ktorých význam spresňuje alebo doplňuje, na- príklad v kombinácii so značkou č. A 2a udáva skutočný celkový počet zákrut.');
INSERT INTO `RoadSigns` VALUES (127,'E','E10','Druh vozidla','e10','Dodatková tabuľka Druh vozidla (č. E 10) obmedzuje platnosť značky, pod ktorou je umiestnená, na vyznačený druh vozidla; tento druh vozidla sa vyznačuje významovými symbolmi zo zákazových značiek.');
INSERT INTO `RoadSigns` VALUES (128,'E','E11','Tvar kríženia cesty so železničnou dráhou','e11','Dodatková tabuľka Tvar kríženia cesty so železničnou dráhou (č. E 11) vyznačuje taký tvar kríženia cesty so železnič- nou dráhou tam, kde nie je dostatočný rozhľad alebo kde má kríženie ostrý uhol. Umiestňuje sa nad značky č. A 29a a č. A 29b – 80 m.');
INSERT INTO `RoadSigns` VALUES (129,'E','E12','Dodatková tabuľka s textom','e12','Dodatková tabuľka s textom (č. E 12) s nápisom „OKREM ZÁSOBOVANIA“ obmedzuje platnosť značky, pod ktorou je umiestnená, na vozidlá zabezpečujúce zásobovanie, opravárenské, údržbárske alebo komunálne a podobné služby, na vozidlá s parkovacím preukazom pre osoby so zdravotným postihnutím alebo na vozidlá s osobitným označením č. O 3; pre tieto vozidlá neplatí značka, pod ktorou je tabuľka umiestnená. - Dodatková tabuľka s textom (č. E 12) s nápisom „OKREM DOPRAVNEJ OBSLUHY“ obmedzuje platnosť značky, pod ktorou je umiestnená, na vozidlá zabezpečujúce zásobovanie, opravárenské, údržbárske alebo komunálne a podobné služby, na vozidlá s parkovacím preukazom pre osoby so zdravotným postihnutím alebo na vozidlá s osobitným označením č. O 3, na vozidlá taxislužby a vozidlá, ktorých vodiči, prípadne prevádzkovatelia majú v miestach za značkou bydlisko, sídlo alebo garáž; pre tieto vozidlá neplatí značka, pod ktorou je tabuľka umiestnená. - Dodatkovú tabuľku s textom (č. E 12) možno použiť v prípadoch, keď je nutné obmedziť platnosť zákazu vyplývajúceho z príslušnej zákazovej alebo príkazovej značky len pre určitú skupinu alebo vozidlá, napríklad v kombinácii so značkou č. B 1 s textom „OKREM...“ vozidiel z presne vymedzenej skupiny alebo so stanoveným evidenčným číslom, a to vždy jednoznačným, vhodným a presným údajom. - Dodatkovú tabuľku s textom (č. E 12) možno použiť podľa odsekov 15 až 17 len v kombinácii so značkami č. B 1 až B 12, č. B 13 až B 18, č. B 27a až B 28, č. B 33 až B 37 a so značkami č. C 1 až C 5. - Dodatkovú tabuľku s textom (č. E 12) možno použiť k značkám ako spoločnú dodatkovú tabuľku na spresňujúce údaje. - Dodatkovú tabuľku s textom (č. E 12) možno použiť na vyznačenie výnimky z miestnej úpravy cestnej premávky pre vodičov električky a vyznačuje sa len vtedy, keď to vyžaduje situácia v cestnej premávke.');
INSERT INTO `RoadSigns` VALUES (130,'E','E13','Dodatková tabuľka pre vyhradené parkovanie','e13','Dodatková tabuľka pre vyhradené parkovanie (č. E 13) sa používa v kombinácii so značkou č. IP 16 ako tabuľka pre spresňujúce údaje.');
INSERT INTO `RoadSigns` VALUES (131,'E','E14','Kategória tunela','e14','Dodatkovú tabuľku Kategória tunela (č. E 14)11) možno použiť v kombinácii so značkami č. A 24, č. B 21, č. C 19, č. IP 21a, č. IP 21b. Významový symbol tabuľky možno vložiť do prednej strany príslušnej značky zo skupiny IS. Vzhľadom na zákaz cestnej prepravy nebezpečných vecí sa na tabuľke miesto údaja (*) uvedie aktuálny údaj jedného z písmen B, C, D alebo E.');
INSERT INTO `RoadSigns` VALUES (132,'E','E15','Dodatková tabuľka na označenie vyhradeného parkovacieho miesta pre osobu so zdravotným postihnutím','e15','Dodatková tabuľka na označenie vyhradeného parkovacieho miesta pre osobu so zdravotným postihnutím (č. E 15) sa používa najmä v kombinácii so značkou č. IP 16; významový symbol tabuľky možno vložiť do prednej strany znač- ky č. IP 16 vpravo nad nápis „RÉSERVÉ“.');
INSERT INTO `RoadSigns` VALUES (133,'E','E16a','Povolený smer jazdy cyklistov','e16a','');
INSERT INTO `RoadSigns` VALUES (134,'E','E16b','Jazda cyklistov v protismere povolená','e16b','');
INSERT INTO `RoadSigns` VALUES (135,'E','E16c','Jazda cyklistov v oboch smeroch povolená','e16c','');
INSERT INTO `RoadSigns` VALUES (136,'E','E16d','Priečna jazda cyklistov','e16d','');
INSERT INTO `RoadSigns` VALUES (137,'E','E2','Vzdialenosť','e2','Dodatková tabuľka Vzdialenosť (č. E 2) vyznačuje vzdialenosť k miestu, od ktorého platí značka, pod ktorou je umiestnená.');
INSERT INTO `RoadSigns` VALUES (138,'E','E3','Vzdialenosť','e3','Dodatková tabuľka Vzdialenosť (č. E 3) umiestnená pod značkou č. P 1 vyznačuje vzdialenosť k značke č. P 2, pre ktorú je zároveň predbežnou značkou. Na tabuľke sa uvádza vzdialenosť v celých desiatkach metrov k miestu, kde platí povinnosť zastaviť vozidlo.');
INSERT INTO `RoadSigns` VALUES (139,'E','E4','Dĺžka úseku alebo platnosti','e4','Dodatková tabuľka Dĺžka úseku alebo platnosti (č. E 4) vyznačuje dĺžku úseku alebo platnosti značky, pod ktorou je umiestnená. Používa sa najmä v kombinácii s výstražnými značkami, ktoré upozorňujú na nebezpečenstvo v určitom úseku.');
INSERT INTO `RoadSigns` VALUES (140,'E','E5a','Úsek platnosti','e5a','Dodatková tabuľka Úsek platnosti (č. E 5a) vyznačuje smer k miestu, kde platí značka a úsek platnosti, pre ktorý platí značka, pod ktorou je umiestnená. Používa sa najmä v spojení so značkami č. B 33 alebo č. B 34.');
INSERT INTO `RoadSigns` VALUES (141,'E','E5b','Úsek platnosti','e5b','Dodatková tabuľka Úsek platnosti (č. E 5b) vyznačuje smer k miestu, kde platí značka a úsek platnosti, pre ktorý platí značka, pod ktorou je umiestnená. Používa sa podľa rovnakých zásad ako dodatková tabuľka č. E 5a.');
INSERT INTO `RoadSigns` VALUES (142,'E','E6','Celková hmotnosť','e6','Dodatková tabuľka Celková hmotnosť (č. E 6) sa používa najmä v kombinácii so značkami č. B 6, č. B 30a až B 31b, ktorých platnosť je potrebné obmedziť len na vozidlá, ktorých najväčšia prípustná celková hmotnosť presahuje údaj uvedený na dodatkovej tabuľke. Pri jazdnej súprave zloženej z jedného alebo z viacerých motorových vozidiel a z jedného alebo z viacerých prípojných vozidiel) rozhoduje súčet najväčších prípustných celkových hmotností vozidiel. údaj sa uvádza v tonách s jedným desatinným miestom.');
INSERT INTO `RoadSigns` VALUES (143,'E','E6a','Celková hmotnosť','e6a','');
INSERT INTO `RoadSigns` VALUES (144,'E','E6b','Celková hmotnosť','e6b','');
INSERT INTO `RoadSigns` VALUES (145,'E','E7','Smerová šípka','e7','Dodatková tabuľka Smerová šípka (č. E 7) označuje smer k miestu, kde platí značka, pod ktorou je umiestnená. Používa sa najmä v spojení so značkami č. IP 12 až IP 19 alebo č. IP 20a a č. IP 20b.');
INSERT INTO `RoadSigns` VALUES (146,'E','E8a','Začiatok úseku platnosti','e8a','Dodatková tabuľka Začiatok úseku platnosti (č. E 8a) vyznačuje začiatok úseku, pre ktorý platí značka, pod ktorou je umiestnená. Používa sa najmä v spojení so značkami č. B 33, č. B 34 alebo so značkami č. IP 12 až IP 19, ak je nutné začiatok úseku platnosti zdôrazniť.');
INSERT INTO `RoadSigns` VALUES (147,'E','E8b','Priebeh úseku platnosti','e8b','Dodatková tabuľka Priebeh úseku platnosti (č. E 8b) vyznačuje priebeh úseku, pre ktorý platí značka, pod ktorou je umiestnená; používa sa najmä, ak je nutné na priebeh platnosti zvlášť upozorniť, v prípade dlhšieho úseku. Používa sa podľa rovnakých zásad ako dodatková tabuľka č. E 8a.');
INSERT INTO `RoadSigns` VALUES (148,'E','E8c','Koniec úseku platnosti','e8c','Dodatková tabuľka Koniec úseku platnosti (č. E 8c) vyznačuje koniec úseku, pre ktorý platí značka, pod ktorou je umiestnená. Používa sa v prípadoch, keď platnosť značky, pod ktorou je umiestnená, má sa skončiť mimo križovatky. Používa sa najmä v kombinácii s dodatkovou tabuľkou č. E 8a.');
INSERT INTO `RoadSigns` VALUES (149,'E','E9','Nepriaznivé poveternostné podmienky','e9','Dodatková tabuľka Nepriaznivé poveternostné podmienky (č. E 9) obmedzuje platnosť značky, pod ktorou je umiestnená. Používa sa najmä v spojení s výstražnými značkami, ktoré upozorňujú na nebezpečenstvo v určitom úseku vozovky, napríklad na podmienky mokrej vozovky alebo iné nepriaznivé poveternostné podmienky.');
INSERT INTO `RoadSigns` VALUES (150,'II','II10','Hotel alebo motel','ii10','Značka Hotel alebo motel (č. II 10) informuje o blízkosti hotela alebo motela.');
INSERT INTO `RoadSigns` VALUES (151,'II','II11','Reštaurácia','ii11','Značka Reštaurácia (č. II 11) informuje o blízkosti reštaurácie.');
INSERT INTO `RoadSigns` VALUES (152,'II','II12','Občerstvenie','ii12','Značka Občerstvenie (č. II 12) informuje o blízkosti zariadenia, v ktorom sa poskytuje občerstvenie.');
INSERT INTO `RoadSigns` VALUES (153,'II','II13','WC','ii13','Značka WC (č. II 13) informuje o blízkosti verejne prístupného WC.');
INSERT INTO `RoadSigns` VALUES (154,'II','II14','Odpočívadlo','ii14','Značka Odpočívadlo (č. II 14) označuje miesto mimo obce, na ktorom je dovolené zastavenie a státie, a to najmä ak sa nachádza mimo cesty. Odpočívadlo určené pre určitý druh vozidiel sa označuje v kombinácii s dodatkovou tabuľkou č. E 10 so zodpovedajúcim symbolom.');
INSERT INTO `RoadSigns` VALUES (155,'II','II15a','Táborisko pre stany','ii15a','Značka Táborisko pre stany (č. II 15a) informuje o blízkosti táboriska pre stany.');
INSERT INTO `RoadSigns` VALUES (156,'II','II15b','Táborisko pre obytné prívesy','ii15b','Značka Táborisko pre obytné prívesy (č. II 15b) informuje o blízkosti táboriska pre obytné prívesy.');
INSERT INTO `RoadSigns` VALUES (157,'II','II15c','Táborisko pre stany a obytné prívesy','ii15c','Značka Táborisko pre stany a obytné prívesy (č. II 15c) informuje o blízkosti táboriska pre stany a obytné prívesy.');
INSERT INTO `RoadSigns` VALUES (158,'II','II16','Pláž alebo kúpalisko','ii16','Značka Pláž alebo kúpalisko (č. II 16) vyznačuje letné stredisko cestovného ruchu a informuje o blízkosti pláže alebo kúpaliska.');
INSERT INTO `RoadSigns` VALUES (159,'II','II17a','Lyžiarsky vlek','ii17a','Značky Lyžiarsky vlek, Sedačkový vlek a Kabínková lanovka (č. II 17a, č. II 17b a č. II 17c) vyznačujú spravidla zimné stredisko cestovného ruchu a informujú o blízkosti lyžiarskeho strediska alebo vyhliadkovej lanovky.');
INSERT INTO `RoadSigns` VALUES (160,'II','II17b','Sedačková lanovka','ii17b','Značky Lyžiarsky vlek, Sedačkový vlek a Kabínková lanovka (č. II 17a, č. II 17b a č. II 17c) vyznačujú spravidla zimné stredisko cestovného ruchu a informujú o blízkosti lyžiarskeho strediska alebo vyhliadkovej lanovky.');
INSERT INTO `RoadSigns` VALUES (161,'II','II17c','Kabínková lanovka','ii17c','Značky Lyžiarsky vlek, Sedačkový vlek a Kabínková lanovka (č. II 17a, č. II 17b a č. II 17c) vyznačujú spravidla zimné stredisko cestovného ruchu a informujú o blízkosti lyžiarskeho strediska alebo vyhliadkovej lanovky.');
INSERT INTO `RoadSigns` VALUES (162,'II','II18a','Odpočívadlo s objektmi služieb (vzor)','ii18a','Značky Odpočívadlo s objektmi služieb (č. II 18a, č. II 18b a č. II 18c) sa používajú na diaľnici alebo na rýchlostnej ces- te na označenie polohy a vzdialenosti k odpočívadlu. Na dodatkovej tabuli pod značkou Odpočívadlo s objektmi služieb č. II 18a sú uvedené informácie o najbližšom nasledujúcom odpočívadle a o vzdialenosti k nemu, prípadne aj informácie o čísle cesty.');
INSERT INTO `RoadSigns` VALUES (163,'II','II18b','Odpočívadlo s objektmi služieb (vzor)','ii18b','Značky Odpočívadlo s objektmi služieb (č. II 18a, č. II 18b a č. II 18c) sa používajú na diaľnici alebo na rýchlostnej ces- te na označenie polohy a vzdialenosti k odpočívadlu. Na dodatkovej tabuli pod značkou Odpočívadlo s objektmi služieb č. II 18a sú uvedené informácie o najbližšom nasledujúcom odpočívadle a o vzdialenosti k nemu, prípadne aj informácie o čísle cesty.');
INSERT INTO `RoadSigns` VALUES (164,'II','II18c','Odpočívadlo s objektmi služieb (vzor)','ii18c','Značky Odpočívadlo s objektmi služieb (č. II 18a, č. II 18b a č. II 18c) sa používajú na diaľnici alebo na rýchlostnej ces- te na označenie polohy a vzdialenosti k odpočívadlu. Na dodatkovej tabuli pod značkou Odpočívadlo s objektmi služieb č. II 18a sú uvedené informácie o najbližšom nasledujúcom odpočívadle a o vzdialenosti k nemu, prípadne aj informácie o čísle cesty.');
INSERT INTO `RoadSigns` VALUES (165,'II','II19a','Núdzový východ','ii19a','Značky Núdzové východy (č. II 19a a č. II 19b) sa používajú na označenie núdzových východov v tuneloch, rovnaké uvedené značky sa používajú pre všetky druhy núdzových východov.');
INSERT INTO `RoadSigns` VALUES (166,'II','II19b','Núdzový východ','ii19b','Značky Núdzové východy (č. II 19a a č. II 19b) sa používajú na označenie núdzových východov v tuneloch, rovnaké uvedené značky sa používajú pre všetky druhy núdzových východov.');
INSERT INTO `RoadSigns` VALUES (167,'II','II1a','Telefón núdzového volania','ii1a','Značka Telefón núdzového volania (č. II 1a) informuje o mieste, kde je na ceste umiestnený telefón núdzového volania s vybudovaným systémom telefónnych hlások; značka sa môže použiť aj ako značka predbežná s informovaním o smere a prípadne o vzdialenosti.');
INSERT INTO `RoadSigns` VALUES (168,'II','II1b','Núdzové volanie','ii1b','Značka Núdzové volanie (č. II 1b) informuje o telefónnej linke 112 na integrovaný záchranný systém núdzovej pomoci alebo v kombinácii s dodatkovou tabuľkou č. E 12 vhodným nápisom alebo symbolom aj o jednotlivých telefónnych linkách núdzového volania, prípadne o ich internetových adresách.');
INSERT INTO `RoadSigns` VALUES (169,'II','II1c','Kontrola rýchlosti','ii1c','');
INSERT INTO `RoadSigns` VALUES (170,'II','II2','Telefón','ii2','Značka Telefón (č. II 2) informuje o blízkosti miesta, kde je verejne prístupný telefónny prístroj.');
INSERT INTO `RoadSigns` VALUES (171,'II','II20a','Úniková cesta (vzor)','ii20a','Značky Únikové cesty (č. II 20a, č. II 20b a č. 20c) sa používajú na označenie smeru k dvom najbližším núdzovým východom v tuneli; dva najbližšie núdzové východy musia byť označené na bočných stenách vo vzdialenosti najviac 25 m a vo výške 1 m až 1,5 m nad úrovňou únikovej cesty vyznačením vzdialenosti k východom.');
INSERT INTO `RoadSigns` VALUES (172,'II','II20b','Úniková cesta (vzor)','ii20b','Značky Únikové cesty (č. II 20a, č. II 20b a č. 20c) sa používajú na označenie smeru k dvom najbližším núdzovým východom v tuneli; dva najbližšie núdzové východy musia byť označené na bočných stenách vo vzdialenosti najviac 25 m a vo výške 1 m až 1,5 m nad úrovňou únikovej cesty vyznačením vzdialenosti k východom.');
INSERT INTO `RoadSigns` VALUES (173,'II','II20c','Úniková cesta (vzor)','ii20c','Značky Únikové cesty (č. II 20a, č. II 20b a č. 20c) sa používajú na označenie smeru k dvom najbližším núdzovým východom v tuneli; dva najbližšie núdzové východy musia byť označené na bočných stenách vo vzdialenosti najviac 25 m a vo výške 1 m až 1,5 m nad úrovňou únikovej cesty vyznačením vzdialenosti k východom.');
INSERT INTO `RoadSigns` VALUES (174,'II','II21a','Úhrada mýta','ii21a','');
INSERT INTO `RoadSigns` VALUES (175,'II','II21b','Koniec úhrady mýta','ii21b','');
INSERT INTO `RoadSigns` VALUES (176,'II','II22a','Úhrada diaľničnou nálepkou','ii22a','');
INSERT INTO `RoadSigns` VALUES (177,'II','II22b','Koniec úhrady diaľničnou nálepkou','ii22b','');
INSERT INTO `RoadSigns` VALUES (178,'II','II3','Hasiaci prístroj','ii3','Značka Hasiaci prístroj (č. II 3) informuje o mieste, kde je umiestnený hasiaci prístroj.');
INSERT INTO `RoadSigns` VALUES (179,'II','II4','Prvá pomoc','ii4','Značka Prvá pomoc (č. II 4) informuje o blízkosti zariadenia, v ktorom je poskytovaná služba prvej pomoci.');
INSERT INTO `RoadSigns` VALUES (180,'II','II5','Nemocnica','ii5','Značka Nemocnica (č. II 5) informuje o blízkosti nemocnice.');
INSERT INTO `RoadSigns` VALUES (181,'II','II6a','Informácie','ii6a','Značka Informácie (č. II 6) informuje o blízkosti miesta, kde možno dostať najmä turistické informácie.');
INSERT INTO `RoadSigns` VALUES (182,'II','II6b','Rádio (vzor)','ii6b','Značka Rádio (č. II 6b) informuje o rozhlasovej stanici, ktorej obsahom vysielania sú pravidelné dopravné informácie, ktoré obsahujú aktuálne dopravné a cestovné informácie o situácii v cestnej premávke a ktoré majú vplyv na bezpečnosť a plynulosť cestnej premávky.');
INSERT INTO `RoadSigns` VALUES (183,'II','II7a','Zastávka autobusu','ii7a','Značka Zastávka autobusu (č. II 7a) označuje zastávku autobusov. Značka č. II 7a sa používa na označenie zastávky, ak umiestnenie zastávky nie je dostatočne zreteľné.');
INSERT INTO `RoadSigns` VALUES (184,'II','II7b','Zastávka trolejbusu','ii7b','Značka Zastávka trolejbusu (č. II 7b) označuje zastávku trolejbusu.');
INSERT INTO `RoadSigns` VALUES (185,'II','II7c','Zastávka električky','ii7c','Značka Zastávka električky (č. II 7c) označuje zastávku električky bez nástupného ostrovčeka.');
INSERT INTO `RoadSigns` VALUES (186,'II','II8a','Čerpacia stanica','ii8a','Značka čerpacia stanica (č. II 8a) informuje o blízkosti čerpacej stanice pohonných hmôt.');
INSERT INTO `RoadSigns` VALUES (187,'II','II8b','Čerpacia stanica skvapalneného ropného plynu (LPG)','ii8b','Značka čerpacia stanica skvapalneného ropného plynu (LPG) (č. II 8b) informuje o blízkosti čerpacej stanice skvapalneného ropného plynu (LPG).');
INSERT INTO `RoadSigns` VALUES (188,'II','II8c','Čerpacia stanica skvapalneného ropného plynu (CNG)','ii8c','Značka čerpacia stanica stlačeného prírodného plynu (CNG) (č. II 8c) informuje o blízkosti čerpacej stanice stlačené- ho prírodného plynu (CNG).');
INSERT INTO `RoadSigns` VALUES (189,'II','II9','Opraváreň','ii9','Značka Opraváreň (č. II 9) informuje o blízkosti opravovne motorových vozidiel alebo o predajni motorových vozidiel poskytujúcej servisné služby; ak ide o autorizovanú predajňu motorových vozidiel poskytujúcu servisné služby, možno na dodatkovej tabuľke č. E 12 uviesť typy alebo druhy vozidiel.');
INSERT INTO `RoadSigns` VALUES (190,'IP','IP1','Okruh','ip1','Značka Okruh (č. IP 1) označuje okruh zriadený na obchádzanie obce alebo jej časti. Ak je zriadených viac okruhov, označujú sa v spodnej časti značky rímskymi číslicami postupne od stredu obce. Pri súbehu viac okruhov na jednej ceste sa v spodnej časti značky označí každý okruh. Podporne sa používajú aj pruhy rovnakej farby na stĺpoch verejného osvetlenia a podobne.');
INSERT INTO `RoadSigns` VALUES (191,'IP','IP10','Odporúčaná rýchlosť','ip10','Značka Odporúčaná rýchlosť (č. IP 10) informuje o odporúčanej rýchlosti za normálnych podmienok; odporúčaná rýchlosť sa vyznačuje číslom alebo číslami v kilometroch za hodinu.');
INSERT INTO `RoadSigns` VALUES (192,'IP','IP11','Núdzová odstavná plocha','ip11','Značka Núdzová odstavná plocha (č. IP 11) informuje o mieste vyhradenom na núdzové státie vozidla.');
INSERT INTO `RoadSigns` VALUES (193,'IP','IP12','Parkovisko','ip12','Značka Parkovisko (č. IP 12) označuje miesto alebo priestor, kde je dovolené zastavenie a státie vozidiel; ak je použitá spolu s dodatkovou tabuľkou č. E 10 s príslušným symbolom druhu vozidla, označuje miesto alebo priestor, kde je dovolené státie vozidiel len pre určitý druh vozidiel. Ak sa značka použije ako predbežná značka, údaj o polohe alebo o vzdialenosti možno vyznačiť v spodnej časti značky alebo možno použiť príslušné dodatkové tabuľky, napríklad dodatkovú tabuľku č. E 7 alebo č. E 2. ďalšie spresňujúce údaje možno uviesť na dodatkovej tabuľke č. E 12.');
INSERT INTO `RoadSigns` VALUES (194,'IP','IP13a','Parkovisko (kolmé státie)','ip13a','Značka Parkovisko – parkovacie miesta s kolmým státím (č. IP 13a) označuje miesto alebo priestor, kde je dovolené zastavenie a státie vozidiel a označuje predpísaný spôsob státia vozidiel. Vyhotovenie symbolu parkovacieho státia predpisuje spôsob státia z hľadiska situovania vozidla, najmä vo vzťahu k okraju vozovky. V prípadoch, ak je vyznačený symbol vozidla, ktorý môže byť obrátený, je určený dovolený spôsob státia vozidla z hľadiska situovania státia vozidla vo vyznačenom parkovacom státí, napríklad státie prednou alebo zadnou časťou vozidla vo vyznačenom parkovacom státí. Ak sa pod značku umiestni dodatková tabuľka č. E 10 s príslušným symbolom druhu vozidla, vodiči iného druhu vozidiel nemôžu na takto označenom mieste stáť, ak to nie je inak dovolené.');
INSERT INTO `RoadSigns` VALUES (195,'IP','IP13b','Parkovisko (šikmé státie)','ip13b','Značka Parkovisko – parkovacie miesta so šikmým státím (č. IP 13b) vyznačuje a určuje dovolený šikmý spôsob státia vozidiel vo vzťahu k okraju vozovky a používa sa podľa rovnakých podmienok ako značka č. IP 13a s tým rozdielom, že sa používa vždy so značkou č. V 10b.');
INSERT INTO `RoadSigns` VALUES (196,'IP','IP13c','Parkovisko (pozdĺžne státie)','ip13c','Značka Parkovisko – parkovacie miesta s pozdĺžnym státím (č. IP 13c) vyznačuje a určuje dovolený spôsob státia vozidiel len pozdĺžne vo vzťahu k okraju vozovky a používa sa podľa rovnakých podmienok ako značka č. IP 13a.');
INSERT INTO `RoadSigns` VALUES (197,'IP','IP14a','Parkovisko (státie na chodníku kolmé alebo šikmé)','ip14a','Značka Parkovisko – parkovacie miesta s kolmým alebo šikmým státím na chodníku (č. IP 14a) vyznačuje a určuje dovolený spôsob státia vozidiel na chodníku. Používa sa podľa rovnakých podmienok ako značka č. IP 13a alebo č. IP 13b s tým rozdielom, že vyznačuje dovolené státie na chodníku a vždy sa používa spolu s príslušnou vodorovnou značkou; na miestach, kde je dovolené státie vozidiel na chodníku, nesmie zastaviť ani stáť vozidlo s najväčšou prípustnou celkovou hmotnosťou prevyšujúcou 3 500 kg a zvláštne motorové vozidlo.');
INSERT INTO `RoadSigns` VALUES (198,'IP','IP14b','Parkovisko (státie na chodníku pozdĺžne)','ip14b','Značka Parkovisko – parkovacie miesta s pozdĺžnym státím na chodníku (č. IP 14b) vyznačuje a určuje dovolený spôsob státia vozidiel na chodníku. Používa sa podľa rovnakých podmienok ako značka č. IP 14a.');
INSERT INTO `RoadSigns` VALUES (199,'IP','IP15a','Parkovisko (čiastočné státie na chodníku kolmé alebo šikmé)','ip15a','Značka Parkovisko – parkovacie miesta s kolmým alebo šikmým čiastočným státím na chodníku (č. IP 15a) vyznačuje a určuje dovolený spôsob státia vozidiel na chodníku. Používa sa podľa rovnakých podmienok ako značka č. IP 14a s tým rozdielom, že vyznačuje iba dovolené čiastočné státie na chodníku.');
INSERT INTO `RoadSigns` VALUES (200,'IP','IP15b','Parkovisko (čiastočné státie na chodníku pozdĺžne)','ip15b','Značka Parkovisko – parkovacie miesta s pozdĺžnym čiastočným státím na chodníku (č. IP 15b) vyznačuje a určuje dovolený spôsob státia vozidiel na chodníku. Používa sa podľa rovnakých podmienok ako značka č. IP 14a s tým rozdielom, že vyznačuje iba dovolené čiastočné státie na chodníku.');
INSERT INTO `RoadSigns` VALUES (201,'IP','IP16','Vyhradené parkovisko','ip16','Značka Parkovisko – parkovacie miesta s vyhradeným státím (č. IP 16) označuje určené (vyhradené) parkovisko, kde zastavenie a státie je dovolené len pre určité vozidlo. Okrem času, v ktorom je parkovisko vyhradené, môžu na takto označenom parkovisku zastaviť a stáť aj vodiči iných vozidiel, ak to nie je zakázané.');
INSERT INTO `RoadSigns` VALUES (202,'IP','IP17a','Platené parkovisko (parkovacie miesta s plateným státím)','ip17a','Značka Parkovisko – parkovacie miesta s plateným státím (č. IP 17a) informuje o povinnom platenom parkovacom státí a označuje parkovisko, kde zastavenie a státie vozidiel je dovolené len za dodržania podmienok vyplývajúcich z použitej značky. Inak je vodičom vozidiel na takto označenom mieste zastavenie a státie zakázané.');
INSERT INTO `RoadSigns` VALUES (203,'IP','IP17b','Platené parkovisko (parkovacie miesta s regulovaným státím)','ip17b','Značka Parkovisko – parkovacie miesta s regulovaným státím (č. IP 17b) informuje o časovo regulovanom parkovisku a označuje parkovisko, kde zastavenie a státie vozidiel je dovolené len za dodržania podmienok vyplývajúcich z použitej značky, napríklad za dodržania maximálne dovolenej doby parkovania alebo za podmienky použitia parkovacieho kotúča alebo parkovacej karty, ktorá musí byť zreteľne a viditeľne umiestnená v prednej časti vozidla. Inak je vodičom vozidiel na takto označenom mieste zastavenie a státie zakázané.');
INSERT INTO `RoadSigns` VALUES (204,'IP','IP18','Kryté parkovisko','ip18','Značka Kryté parkovisko, parkovacia garáž, parkovací dom (č. IP 18) informuje o krytom parkovisku alebo o parkovacej garáži. Dovolený spôsob státia sa vyznačuje podľa rovnakých podmienok ako pri značke č. IP 12.');
INSERT INTO `RoadSigns` VALUES (205,'IP','IP19','Parkovisko P+R','ip19','Značka Parkovisko P + R (č. IP 19) informuje o parkovisku, z ktorého možno cestovať vozidlom pravidelnej verejnej dopravy. Spresňujúce údaje, napríklad čas a podobne, sa môžu vyznačiť v spodnej časti značky vhodným nápisom, symbolom alebo na dodatkovej tabuľke č. E 12.');
INSERT INTO `RoadSigns` VALUES (206,'IP','IP2','Zmena smeru okruhu','ip2','Značka Zmena smeru okruhu (č. IP 2) informuje, že na najbližšej križovatke trasa okruhu nepokračuje v priamom smere. Zmena smeru je vyznačená šípkou na značke, ktorej významový symbol môže byť obrátený.');
INSERT INTO `RoadSigns` VALUES (207,'IP','IP20a','Stanovište polície','ip20a','Značka Stanovište polície (č. IP 20a) informuje o blízkosti stanovišťa alebo útvaru Policajného zboru.');
INSERT INTO `RoadSigns` VALUES (208,'IP','IP20b','Stanovište taxi','ip20b','Značka Stanovište taxi (č. IP 20b) informuje o stanovišti taxíkov, kde zastavenie a státie vozidiel je dovolené len pre vozidlá taxislužby. Okrem času, v ktorom je stanovište taxi určené, môžu na takto označenom stanovišti zastaviť a stáť aj vodiči iných vozidiel, ak to nie je zakázané.');
INSERT INTO `RoadSigns` VALUES (209,'IP','IP21a','Tunel','ip21a','Značka Tunel (č. IP 21a) označuje blízkosť vjazdu do tunela, kde platia pravidlá cestnej premávky pre správanie v tuneli.');
INSERT INTO `RoadSigns` VALUES (210,'IP','IP21b','Koniec tunela','ip21b','Značka Koniec tunela (č. IP 21b) označuje miesto, kde sa končí platnosť pravidiel cestnej premávky pre správanie v tuneli.');
INSERT INTO `RoadSigns` VALUES (211,'IP','IP22a','Rýchlostná cesta','ip22a','Značka Rýchlostná cesta (č. IP 22a) označuje cestu, na ktorej platia zvláštne ustanovenia o premávke na diaľnici a rýchlostnej ceste. Rýchlostné cesty, ktoré nie sú spoplatnené, sa označujú dodatkovou tabuľkou s textom „BEZ ÚHRADY“ v troch jazykoch.9)');
INSERT INTO `RoadSigns` VALUES (212,'IP','IP22b','Koniec rýchlostnej cesty','ip22b','Značka Koniec rýchlostnej cesty (č. IP 22b) označuje koniec cesty, na ktorej platia zvláštne ustanovenia o premávke na diaľnici a rýchlostnej ceste.');
INSERT INTO `RoadSigns` VALUES (213,'IP','IP23a','Diaľnica','ip23a','Značka Diaľnica (č. IP 23a) označuje cestu, na ktorej platia zvláštne ustanovenia o premávke na diaľnici a rýchlostnej ceste. Diaľnice, ktoré nie sú spoplatnené, sa označujú dodatkovou tabuľkou s textom „BEZ ÚHRADY“ v troch jazykoch.9)');
INSERT INTO `RoadSigns` VALUES (214,'IP','IP23b','Koniec diaľnice','ip23b','Značka Koniec diaľnice (č. IP 23b) označuje koniec cesty, na ktorej platia zvláštne ustanovenia o premávke na diaľnici a rýchlostnej ceste.');
INSERT INTO `RoadSigns` VALUES (215,'IP','IP24a','Zóna s dopravným obmedzením','ip24a','Značky Zóna s dopravným obmedzením (č. IP 24a) a Koniec zóny s dopravným obmedzením (č. IP 24b) vyznačujú oblasť (časť obce a podobne), kde platí zákaz alebo obmedzenie vyplývajúce z použitých symbolov značky alebo značiek.');
INSERT INTO `RoadSigns` VALUES (216,'IP','IP24b','Koniec zóny s dopravným obmedzením','ip24b','Značky Zóna s dopravným obmedzením (č. IP 24a) a Koniec zóny s dopravným obmedzením (č. IP 24b) vyznačujú oblasť (časť obce a podobne), kde platí zákaz alebo obmedzenie vyplývajúce z použitých symbolov značky alebo značiek.');
INSERT INTO `RoadSigns` VALUES (217,'IP','IP25a','Pešia zóna','ip25a','Značky Pešia zóna (č. IP 25a) a Koniec pešej zóny (č. IP 25b) vyznačujú územie (časť obce a podobne) určené predovšetkým pre chodcov, kde platia zvláštne ustanovenia o premávke v pešej zóne.');
INSERT INTO `RoadSigns` VALUES (218,'IP','IP25b','Koniec pešej zóny','ip25b','Značky Pešia zóna (č. IP 25a) a Koniec pešej zóny (č. IP 25b) vyznačujú územie (časť obce a podobne) určené predovšetkým pre chodcov, kde platia zvláštne ustanovenia o premávke v pešej zóne.');
INSERT INTO `RoadSigns` VALUES (219,'IP','IP26a','Školská zóna','ip26a','Značky Školská zóna (č. IP 26a) a Koniec školskej zóny (č. IP 26b) vyznačujú oblasť, kde platia zvláštne ustanovenia o premávke v školskej zóne.');
INSERT INTO `RoadSigns` VALUES (220,'IP','IP26b','Koniec školskej zóny','ip26b','Značky Školská zóna (č. IP 26a) a Koniec školskej zóny (č. IP 26b) vyznačujú oblasť, kde platia zvláštne ustanovenia o premávke v školskej zóne.');
INSERT INTO `RoadSigns` VALUES (221,'IP','IP27a','Zóna s plateným parkovaním','ip27a','Značky Zóna s plateným alebo regulovaným státím (č. IP 27a) a Koniec zóny s plateným alebo regulovaným státím (č. IP 27b) vyznačujú oblasť, kde státie vozidiel je dovolené len na vyznačených parkovacích miestach a za dodržania podmienok vyplývajúcich z použitého symbolu príslušnej značky a spresňujúcich údajov, napríklad času regulácie alebo platenia, spôsobu platenia alebo regulovania a podobne. Inak je vodičom vozidiel na takto označenom území stáť zakázané. Symbol značky č. IP 17a možno v prípade potreby zameniť za symbol značky č. IP 17b.');
INSERT INTO `RoadSigns` VALUES (222,'IP','IP27b','Koniec zóny s plateným parkovaním','ip27b','Značky Zóna s plateným alebo regulovaným státím (č. IP 27a) a Koniec zóny s plateným alebo regulovaným státím (č. IP 27b) vyznačujú oblasť, kde státie vozidiel je dovolené len na vyznačených parkovacích miestach a za dodržania podmienok vyplývajúcich z použitého symbolu príslušnej značky a spresňujúcich údajov, napríklad času regulácie alebo platenia, spôsobu platenia alebo regulovania a podobne. Inak je vodičom vozidiel na takto označenom území stáť zakázané. Symbol značky č. IP 17a možno v prípade potreby zameniť za symbol značky č. IP 17b.');
INSERT INTO `RoadSigns` VALUES (223,'IP','IP28a','Obytná zóna','ip28a','Značky Obytná zóna (č. IP 28a) a Koniec obytnej zóny (č. IP 28b) vyznačujú oblasť, kde platia zvláštne ustanovenia o premávke v obytnej zóne.');
INSERT INTO `RoadSigns` VALUES (224,'IP','IP28b','Koniec obytnej zóny','ip28b','Značky Obytná zóna (č. IP 28a) a Koniec obytnej zóny (č. IP 28b) vyznačujú oblasť, kde platia zvláštne ustanovenia o premávke v obytnej zóne.');
INSERT INTO `RoadSigns` VALUES (225,'IP','IP29','Úniková zóna','ip29','Značka Úniková zóna (č. IP 29) informuje o možnosti núdzového zastavenia vozidla v prípade jeho technickej poruchy.');
INSERT INTO `RoadSigns` VALUES (226,'IP','IP30','Zmena miestnej úpravy','ip30','Značka Zmena miestnej úpravy (č. IP 30) vhodným nápisom a symbolom upozorňuje na zmenu miestnej úpravy cestnej premávky, zmenu v organizácii dopravy, nezvyčajné stavebné usporiadanie cesty a podobne.');
INSERT INTO `RoadSigns` VALUES (227,'IP','IP30a','Výstražné zariadenie vypnuté','ip30a','');
INSERT INTO `RoadSigns` VALUES (228,'IP','IP31a','Hmlové body','ip31a','Značky Hmlové body (č. IP 31a, č. IP 31b a č. IP 31c) v spojení so značkou Hmlové body (č. V 17) vyjadrujú odporúčanú rýchlosť v kilometroch za hodinu z dôvodu zníženej viditeľnosti, najmä pri výskyte hmly.');
INSERT INTO `RoadSigns` VALUES (229,'IP','IP31b','Hmlové body','ip31b','Značky Hmlové body (č. IP 31a, č. IP 31b a č. IP 31c) v spojení so značkou Hmlové body (č. V 17) vyjadrujú odporúčanú rýchlosť v kilometroch za hodinu z dôvodu zníženej viditeľnosti, najmä pri výskyte hmly.');
INSERT INTO `RoadSigns` VALUES (230,'IP','IP31c','Hmlové body','ip31c','Značky Hmlové body (č. IP 31a, č. IP 31b a č. IP 31c) v spojení so značkou Hmlové body (č. V 17) vyjadrujú odporúčanú rýchlosť v kilometroch za hodinu z dôvodu zníženej viditeľnosti, najmä pri výskyte hmly.');
INSERT INTO `RoadSigns` VALUES (231,'IP','IP32','Bezpečná vzdialenosť','ip32','Značka Bezpečná vzdialenosť (č. IP 32) v spojení so značkou Bezpečná vzdialenosť (č. V 15) vyjadrujú pri priaznivých dopravných a poveternostných podmienkach odporúčanú vzdialenosť pre vozidlá idúce za sebou, ktorá je zobrazená medzi dvomi vozidlami na značke č. IP 32.');
INSERT INTO `RoadSigns` VALUES (232,'IP','IP33','Všeobecne najvyššie dovolené rýchlosti','ip33','Značka Všeobecné informácie o dopravných obmedzeniach (č. IP 33) informuje o dopravných obmedzeniach v Slovenskej republike ustanovených všeobecnými pravidlami cestnej premávky.');
INSERT INTO `RoadSigns` VALUES (233,'IP','IP33a','Všeobecné informácie o povinnosti úhrady','ip33a','');
INSERT INTO `RoadSigns` VALUES (234,'IP','IP34a','Všeobecné informácie o dopravných obmedzeniach','ip34a','Značky Všeobecné informácie o dopravných obmedzeniach (č. IP 34a až IP 34c) informujú o dopravných situáciách, obmedzeniach cestnej premávky a prejazdnosti horských priechodov a iných kolíznych bodoch, ako je napríklad priesmyk, tunel, most a podobne.');
INSERT INTO `RoadSigns` VALUES (235,'IP','IP34b','Všeobecné informácie o dopravných obmedzeniach','ip34b','Značky Všeobecné informácie o dopravných obmedzeniach (č. IP 34a až IP 34c) informujú o dopravných situáciách, obmedzeniach cestnej premávky a prejazdnosti horských priechodov a iných kolíznych bodoch, ako je napríklad priesmyk, tunel, most a podobne.');
INSERT INTO `RoadSigns` VALUES (236,'IP','IP34c','Všeobecné informácie o dopravných obmedzeniach','ip34c','Značky Všeobecné informácie o dopravných obmedzeniach (č. IP 34a až IP 34c) informujú o dopravných situáciách, obmedzeniach cestnej premávky a prejazdnosti horských priechodov a iných kolíznych bodoch, ako je napríklad priesmyk, tunel, most a podobne.');
INSERT INTO `RoadSigns` VALUES (237,'IP','IP3a','Jednosmerná premávka','ip3a','Značka Jednosmerná premávka (č. IP 3a) označuje jednosmernú cestu, ktorá sa v protismere spravidla označuje značkou č. B 2a; značku možno použiť ako predbežnú značku k značke č. IP 3b.');
INSERT INTO `RoadSigns` VALUES (238,'IP','IP3b','Jednosmerná premávka','ip3b','Značka Jednosmerná premávka (č. IP 3b) označuje jednosmernú cestu, ktorá sa v protismere spravidla označuje značkou č. B 2. Značka sa umiestňuje v mieste, kde sa úsek s jednosmernou premávkou začína.');
INSERT INTO `RoadSigns` VALUES (239,'IP','IP4','Slepá pozemná komunikácia','ip4','Značka Slepá cesta (č. IP 4) označuje cestu, ktorá sa ďalej končí alebo ktorou nemožno ďalej pokračovať v jazde.');
INSERT INTO `RoadSigns` VALUES (240,'IP','IP5','Návesť pred slepou pozemnou komunikáciou','ip5','Značka Návesť pred slepou cestou (č. IP 5) vopred informuje pred križovatkou o ceste, ktorá sa ďalej končí alebo ktorou nemožno ďalej pokračovať v jazde.');
INSERT INTO `RoadSigns` VALUES (241,'IP','IP6','Priechod pre chodcov','ip6','Značka Priechod pre chodcov (č. IP 6) označuje priechod pre chodcov vyznačený značkou č. V 6a alebo č. V 6b.');
INSERT INTO `RoadSigns` VALUES (242,'IP','IP7','Priechod pre cyklistov','ip7','Značka Priechod pre cyklistov (č. IP 7) označuje priechod pre cyklistov vyznačený značkou č. V 7. Pred vstupom na priechod sa musí cyklista presvedčiť, či tak môže urobiť bez nebezpečenstva, a môže naň vstúpiť len vtedy, ak s ohľadom na vzdialenosť a rýchlosť jazdy prichádzajúcich vozidiel nedonúti vodičov náhle zmeniť smer alebo rýchlosť jazdy.');
INSERT INTO `RoadSigns` VALUES (243,'IP','IP8','Spomaľovací prah','ip8','Značka Spomaľovací prah (č. IP 8) informuje na umelú nerovnosť na povrchu vozovky vytvorenú umiestnením prefabrikovaného alebo stavebného spomaľovacieho prahu.');
INSERT INTO `RoadSigns` VALUES (244,'IP','IP9','Podchod alebo nadchod','ip9','Značka Podchod alebo nadchod (č. IP 9) informuje o blízkosti podchodu alebo nadchodu. Bezbariérový podchod alebo nadchod sa označuje spolu s dodatkovou tabuľkou č. E 12 alebo č. E 15.');
INSERT INTO `RoadSigns` VALUES (245,'IS','IS10','Návesť pred križovatkou','is10','Značka Návesť pred križovatkou (č. IS 10) informuje o smere k vyznačeným cieľom z najbližšej okružnej križovatky, prípadne aj o vzdialenosti k nej. Pre farebné vyhotovenie a spôsob uvádzania cieľov a čísel ciest platia podmienky ako pri značke č. IS 9.');
INSERT INTO `RoadSigns` VALUES (246,'IS','IS11','Návesť pred kultúrnym alebo turistickým cieľom','is11','Značka Návesť pred kultúrnym alebo turistickým cieľom (č. IS 11) informuje o významnom kultúrnom alebo turistickom cieli (napríklad hrad, zámok, kúpeľné miesto, jaskyňa a podobne) alebo oblasti; na značke možno použiť vhodný nápis, symbol alebo siluetu konkrétneho cieľa.');
INSERT INTO `RoadSigns` VALUES (247,'IS','IS11a','Návesť pred náboženským cieľom','is11a','');
INSERT INTO `RoadSigns` VALUES (248,'IS','IS12','Návesť pred križovatkou s obmedzením','is12','Značka Návesť pred križovatkou s obmedzením (č. IS 12) informuje o obmedzení premávky za najbližšou križovat- kou. Na značke je podľa potreby vyznačený symbol z príslušnej zákazovej značky.');
INSERT INTO `RoadSigns` VALUES (249,'IS','IS13','Návesť pred križovatkou s obmedzením','is13','Značka Návesť pred križovatkou s obmedzením (č. IS 13) informuje o obmedzení premávky za najbližšou križovatkou a o smere obchádzania. Na značke je podľa potreby vyznačený symbol z príslušnej zákazovej značky.');
INSERT INTO `RoadSigns` VALUES (250,'IS','IS14','Návesť pred križovatkou s obmedzením','is14','Značka Návesť pred križovatkou s obmedzením (č. IS 14) informuje o križovatke, na ktorej je zakázané odbočovať vľavo, a na značke sa súčasne vyznačuje smer jazdy na dosiahnutie cesty v smere obchádzania.');
INSERT INTO `RoadSigns` VALUES (251,'IS','IS15','Návesť pred obchádzkou','is15','Značka Návesť pred obchádzkou (č. IS 15) informuje o uzávierke cesty alebo o obmedzení cestnej premávky a vyznačuje smer a priebeh obchádzkovej trasy. Na značke je podľa potreby uzávierky vyznačený symbol príslušnej zákazovej značky.');
INSERT INTO `RoadSigns` VALUES (252,'IS','IS16','Návesť pred obchádzkou (odklonom)','is16','Značka Návesť pred obchádzkou (odklonom) (č. IS 16) informuje o smere a priebehu obchádzky alebo odklonovej trasy pre uzávierku cesty. Na značke je podľa potreby vyznačená dĺžka uzávierky a dĺžka obchádzky.');
INSERT INTO `RoadSigns` VALUES (253,'IS','IS17a','Smerová tabuľa (s jedným cieľom)','is17a','Značky Smerová tabuľa s jedným cieľom (č. IS 17 a č. IS 17b) informujú o smere a spravidla aj o vzdialenosti v kilometroch k vyznačenému cieľu (obci) a o čísle pokračujúcej cesty, ktoré sa môže na značke doplniť.');
INSERT INTO `RoadSigns` VALUES (254,'IS','IS17b','Smerová tabuľa (s jedným cieľom)','is17b','Značky Smerová tabuľa s jedným cieľom (č. IS 17 a č. IS 17b) informujú o smere a spravidla aj o vzdialenosti v kilometroch k vyznačenému cieľu (obci) a o čísle pokračujúcej cesty, ktoré sa môže na značke doplniť.');
INSERT INTO `RoadSigns` VALUES (255,'IS','IS18a','Smerová tabuľa (s dvomi cieľmi)','is18a','Značky Smerová tabuľa s dvoma cieľmi (č. IS 18a a č. IS 18b) informujú o smere a spravidla aj o vzdialenosti v kilometroch k vyznačeným cieľom (obciam) a o čísle pokračujúcej cesty, ktoré sa môže na značke doplniť.');
INSERT INTO `RoadSigns` VALUES (256,'IS','IS18b','Smerová tabuľa (s dvomi cieľmi)','is18b','Značky Smerová tabuľa s dvoma cieľmi (č. IS 18a a č. IS 18b) informujú o smere a spravidla aj o vzdialenosti v kilometroch k vyznačeným cieľom (obciam) a o čísle pokračujúcej cesty, ktoré sa môže na značke doplniť.');
INSERT INTO `RoadSigns` VALUES (257,'IS','IS19a','Smerová tabuľa pre príjazd k diaľnici','is19a','Značky Smerová tabuľa pre príjazd k diaľnici (č. IS 19a a č. IS 19b) informujú o smere príjazdu k diaľnici, pričom značka č. IS 19a sa nesmie použiť v poslednej križovatke pred odbočením na diaľnicu.');
INSERT INTO `RoadSigns` VALUES (258,'IS','IS19b','Smerová tabuľa pre príjazd k diaľnici','is19b','Značky Smerová tabuľa pre príjazd k diaľnici (č. IS 19a a č. IS 19b) informujú o smere príjazdu k diaľnici, pričom značka č. IS 19a sa nesmie použiť v poslednej križovatke pred odbočením na diaľnicu.');
INSERT INTO `RoadSigns` VALUES (259,'IS','IS1a','Návesť pred križovatkou','is1a','Značka Návesť pred križovatkou (č. IS 1a) informuje na diaľnici a rýchlostnej ceste o názve najbližšej križovatky diaľnic, diaľnice a rýchlostnej cesty alebo rýchlostných ciest s uvedením čísel križujúcich ciest a vzdialenosti k nej.');
INSERT INTO `RoadSigns` VALUES (260,'IS','IS1b','Návesť pred križovatkou','is1b','Značka Návesť pred križovatkou (č. IS 1b) informuje na diaľnici a rýchlostnej ceste o názve a vzdialenosti k najbližšej križovatke a o čísle výjazdu (odbočenia) z priameho smeru diaľnice alebo rýchlostnej cesty, ktoré zodpovedá staničeniu križovatky. Významový symbol značky č. IS 1b s číslom výjazdu bez názvu križovatky sa používa nad každou nasledujúcou návesťou pred križovatkou, ktorá uvádza ciele v smere odbočenia.');
INSERT INTO `RoadSigns` VALUES (261,'IS','IS2','Návesť pred križovatkou','is2','Značka Návesť pred križovatkou (č. IS 2) informuje na diaľnici a rýchlostnej ceste o smeroch k vyznačeným cieľom ležiacim priamo a mimo diaľnice s číslom pokračujúcej cesty. Ako prvý sa uvádza najvzdialenejší cieľ, posledný sa uvedie názov a označenie nasledujúcej križovatky. Na odbočenie sa vždy uvedie aj názov predmetnej križovatky. Vedľa cieľa sa môže uviesť aj číslo cesty, po ktorej je cieľ dosiahnuteľný, aj keď táto cesta nie je pokračujúcou cestou. Základná plocha značky na diaľnici alebo na rýchlostnej ceste je vždy zelenej farby, ak je cieľ dostupný po ceste I., II. alebo III. triedy, uvedie sa na základnej zelenej ploche subplocha modrej farby s uvedením názvu cieľa. Ak sa značka použije na inej ceste, neuvádza sa označenie križovatky a farba podkladovej dosky je modrá. Ak sa použije na miestnych cestách iba na návestenie miestnych a iných cieľov, je farba podkladovej dosky biela, nápisy a šípky (symboly) sú čierne. Miestny cieľ alebo iný cieľ sa uvedie v bielej subploche na základnej zelenej ploche. Na bielej subploche sú texty a symboly čierne. Ak ciele sú dostupné po obchádzkovej alebo odklonovej trase, možno ich vyznačiť na žltej ploche alebo subploche.');
INSERT INTO `RoadSigns` VALUES (262,'IS','IS20a','Smerová tabuľa pre príjazd k rýchlostnej ceste','is20a','Značky Smerová tabuľa pre príjazd k rýchlostnej ceste (č. IS 20a a č. IS 20b) informujú o smere príjazdu k rýchlostnej ceste, pričom značka č. IS 20a sa nesmie použiť v poslednej križovatke pred odbočením na rýchlostnú cestu.');
INSERT INTO `RoadSigns` VALUES (263,'IS','IS20b','Smerová tabuľa pre príjazd k rýchlostnej ceste','is20b','Značky Smerová tabuľa pre príjazd k rýchlostnej ceste (č. IS 20a a č. IS 20b) informujú o smere príjazdu k rýchlostnej ceste, pričom značka č. IS 20a sa nesmie použiť v poslednej križovatke pred odbočením na rýchlostnú cestu.');
INSERT INTO `RoadSigns` VALUES (264,'IS','IS21','Smerová tabuľa k miestnemu cieľu','is21','Značka Smerová tabuľa k miestnemu cieľu (č. IS 21) informuje o smere a prípadne o vzdialenosti k časti obce.');
INSERT INTO `RoadSigns` VALUES (265,'IS','IS22a','Smerová tabuľa k inému cieľu','is22a','Značka Smerová tabuľa k inému cieľu (č. IS 22a) vyznačeným vhodným nápisom, symbolom, piktogramom informuje o smere, prípadne o vzdialenosti k inému významnému cieľu, ako k obci alebo k jej časti, ktorý má dopravný význam pre účastníkov cestnej premávky, napríklad k letisku, k autobusovej alebo železničnej stanici, k prístavu alebo k stanici technickej alebo emisnej kontroly a podobne.');
INSERT INTO `RoadSigns` VALUES (266,'IS','IS22b','Smerová tabuľa k inému cieľu','is22b','Značka Smerová tabuľa k obchodnému centru (č. IS 22b) vyznačeným vhodným nápisom, symbolom, piktogramom informuje o smere, prípadne o vzdialenosti k obchodnému centru.');
INSERT INTO `RoadSigns` VALUES (267,'IS','IS22c','Smerová tabuľa k predajnému miestu','is22c','');
INSERT INTO `RoadSigns` VALUES (268,'IS','IS23a','Smerová tabuľa ku kultúrnemu alebo turistickému cieľu','is23a','Značky Smerová tabuľa ku kultúrnemu alebo turistickému cieľu (č. IS 23a a č. IS 23b) vhodným nápisom, symbolom alebo siluetou informujú o smere, prípadne o vzdialenosti k vyznačenému kultúrnemu alebo turistickému cieľu, napríklad k divadlu, múzeu, galérii a podobne.');
INSERT INTO `RoadSigns` VALUES (269,'IS','IS23b','Smerová tabuľa ku komunálnemu cieľu','is23b','Značky Smerová tabuľa ku kultúrnemu alebo turistickému cieľu (č. IS 23a a č. IS 23b) vhodným nápisom, symbolom alebo siluetou informujú o smere, prípadne o vzdialenosti k vyznačenému kultúrnemu alebo turistickému cieľu, napríklad k divadlu, múzeu, galérii a podobne.');
INSERT INTO `RoadSigns` VALUES (270,'IS','IS23c','Smerová tabuľa k náboženskému cieľu','is23c','');
INSERT INTO `RoadSigns` VALUES (271,'IS','IS23d','Smerová tabuľa k náboženskému cieľu','is23d','');
INSERT INTO `RoadSigns` VALUES (272,'IS','IS24','Smerová tabuľa ku komunálnemu cieľu','is24','Značka Smerová tabuľa ku komunálnemu cieľu (č. IS 24) vhodným nápisom informuje o smere, prípadne o vzdialenosti k vyznačenému komunálnemu cieľu, napríklad k radnici alebo magistrátu a podobne.');
INSERT INTO `RoadSigns` VALUES (273,'IS','IS25','Smerová tabuľa na vyznačenie obchádzky','is25','Značka Smerová tabuľa na vyznačenie obchádzky (č. IS 25) informuje o cieli a smere priebehu obchádzkovej alebo odklonovej trasy. Značka sa používa v prípadoch, keď sa trasy rozdeľujú podľa jednotlivých cieľov alebo keď na tej istej ceste prebieha viac obchádzok alebo odklonov, ktoré smerujú k rozličným cieľom. Vyznačuje smer obchádzky alebo odklonovej trasy pre uzávierku cesty. Značka sa umiestňuje pred každou križovatkou, na ktorej obchádzková alebo odklonová trasa mení smer a tam, kde priebeh obchádzky alebo odklonu nie je jednoznačný. Na značke sa uvádza vzdialenosť k cieľu.');
INSERT INTO `RoadSigns` VALUES (274,'IS','IS26','Smerová tabuľa na vyznačenie obchádzky','is26','Značka Smerová tabuľa na vyznačenie obchádzky (č. IS 26) vyznačuje smer obchádzky alebo odklonovej trasy v celom priebehu až po vyústenie na pôvodnú cestu. Značka sa používa pred každou križovatkou, kde trasa mení smer alebo kde nie je jej priebeh zrejmý, a pred každou významnejšou križovatkou bez ohľadu na ďalší smer trasy. Na vyznačenie priameho smeru sa značka č. IS 26 umiestňuje zvislou šípkou smerujúcou hore.');
INSERT INTO `RoadSigns` VALUES (275,'IS','IS27','Diaľnica','is27','Značka Diaľnica (č. IS 27) informuje o čísle diaľnice; na značke je vyobrazené písmeno „D“ a číslo. Na zlepšenie orientácie sa na diaľnici používa symbol značky č. IS 27 na návestiach pred križovatkami a na smerových tabuliach.');
INSERT INTO `RoadSigns` VALUES (276,'IS','IS28','Rýchlostná cesta','is28','Značka Rýchlostná cesta (č. IS 28) informuje o čísle rýchlostnej cesty; na značke je vyobrazené písmeno „R“ a číslo. Na zlepšenie orientácie sa na rýchlostnej ceste používa symbol značky č. IS 28 na návestiach pred križovatkami a na smerových tabuliach.');
INSERT INTO `RoadSigns` VALUES (277,'IS','IS29','Cesta I. triedy','is29','Značka Cesta I. triedy (č. IS 29) informuje o čísle cesty I. triedy; na značke je vyobrazené číslo. Na zlepšenie orientácie sa na cestách I. triedy používa symbol značky č. IS 29 na návestiach pred križovatkami a na smerových tabuliach.');
INSERT INTO `RoadSigns` VALUES (278,'IS','IS3','Návesť pred križovatkou','is3','Značka Návesť pred križovatkou (č. IS 3) informuje na diaľnici a rýchlostnej ceste o smeroch k vyznačeným cieľom ležiacich priamo a mimo diaľnice s číslom pokračujúcej cesty a o počte a usporiadaní jazdných pruhov. Pre farebné vyhotovenie a spôsob uvádzania cieľov a čísel ciest platia podmienky ako pri značke č. IS 2.');
INSERT INTO `RoadSigns` VALUES (279,'IS','IS30','Cesta II. triedy','is30','Značka Cesta II. triedy (č. IS 30) informuje o čísle cesty II. triedy; na značke je vyobrazené číslo. Na zlepšenie orientácie sa na cestách II. triedy používa symbol značky č. IS 30 na návestiach pred križovatkami a na smerových tabuliach.');
INSERT INTO `RoadSigns` VALUES (280,'IS','IS31','Medzinárodná trasa','is31','Značka Medzinárodná trasa (č. IS 31) informuje o čísle cesty pre medzinárodnú premávku. číslo cesty sa uvádza za písmenom „E“. Na zlepšenie orientácie sa používa symbol značky č. IS 31 na návestiach pred križovatkami a na smerových tabuliach.');
INSERT INTO `RoadSigns` VALUES (281,'IS','IS32a','Kilometrovník','is32a','Značka Kilometrovník (č. IS 32a) vyznačuje vzdialenosť v kilometroch od začiatku cesty. V hornej časti sa uvedie číslo cesty I., II. alebo III. triedy.');
INSERT INTO `RoadSigns` VALUES (282,'IS','IS32b','Kilometrovník','is32b','Značka Kilometrovník (č. IS 32b) vyznačuje vzdialenosť v kilometroch od začiatku diaľnice alebo rýchlostnej cesty a o smere k najbližšiemu stanovišťu núdzového volania. V hornej časti sa uvedie číslo diaľnice alebo rýchlostnej cesty.');
INSERT INTO `RoadSigns` VALUES (283,'IS','IS32c','Kilometrovník','is32c','Značka Kilometrovník (č. IS 32c) informuje, že ak je cesta rozdelená na úseky (tzv. uzly), na značke sa vyznačuje v hornej časti číslo úseku (uzla) a v spodnej časti vzdialenosť v kilometroch od začiatku tohto úseku (uzla). V hornej časti sa uvedie číslo cesty.');
INSERT INTO `RoadSigns` VALUES (284,'IS','IS33','Hranica kraja','is33','Značka Hranica kraja (č. IS 33) vyznačuje na ceste hranicu medzi susediacimi krajmi. Obdobným spôsobom s použi- tím nápisu Slovenská republika možno vyznačiť aj územie republiky.');
INSERT INTO `RoadSigns` VALUES (285,'IS','IS34','Hranica okresu','is34','Značka Hranica okresu (č. IS 34) vyznačuje na ceste hranicu medzi susednými okresmi.');
INSERT INTO `RoadSigns` VALUES (286,'IS','IS35','Iný názov','is35','Značka Iný názov (č. IS 35) informuje o názve mosta, rieky, pohoria, prírodnej rezervácie a podobne; pri názve mosta sa uvedie aj jeho dĺžka.');
INSERT INTO `RoadSigns` VALUES (287,'IS','IS36a','Obec','is36a','Značka Obec (č. IS 36a) a značka Miestna časť obce (č. IS 36c) informujú o názve a o začiatku obce alebo časti obce, pričom vymedzujú miesto, od ktorého platia ustanovenia pravidiel cestnej premávky, ktoré upravujú správanie sa v obci, ako napríklad najvyššia dovolená rýchlosť, jazda v jazdných pruhoch a podobne. Značky č. IS 36a a č. IS 36c končia platnosť značky č. B 31a, ak nie je skôr skončená inak; značky možno použiť samostatne alebo ich kombinovať.');
INSERT INTO `RoadSigns` VALUES (288,'IS','IS36b','Koniec obce','is36b','Značka Koniec obce (č. IS 36b) a značka Koniec miestnej časti obce (č. IS 36d) informujú o skončení obce alebo časti obce z hľadiska platnosti ustanovení pravidiel cestnej premávky, ktoré sa vzťahujú na pravidlá správania sa v obci. Značka č. IS 36b končí platnosť značky č. IS 36a; ak platnosť značky č. IS 36c nebola skôr skončená značkou č. IS 36d, značka č. IS 36b končí platnosť značky č. IS 36c. Značka č. IS 36d končí platnosť značky č. IS 36c; ak platnosť značky č. IS 36a nebola skôr skončená značkou č. IS 36b, značka č. IS 36d končí platnosť značky č. IS 36a. Značky č. IS 36b a č. IS 36d končia platnosť značky č. B 31a, ak nie je skôr skončená inak; značky možno použiť samostatne alebo ich kombinovať.');
INSERT INTO `RoadSigns` VALUES (289,'IS','IS36c','Miestna časť obce','is36c','Značka Obec (č. IS 36a) a značka Miestna časť obce (č. IS 36c) informujú o názve a o začiatku obce alebo časti obce, pričom vymedzujú miesto, od ktorého platia ustanovenia pravidiel cestnej premávky, ktoré upravujú správanie sa v obci, ako napríklad najvyššia dovolená rýchlosť, jazda v jazdných pruhoch a podobne. Značky č. IS 36a a č. IS 36c končia platnosť značky č. B 31a, ak nie je skôr skončená inak; značky možno použiť samostatne alebo ich kombinovať.');
INSERT INTO `RoadSigns` VALUES (290,'IS','IS36d','Koniec miestnej časti obce','is36d','Značka Koniec obce (č. IS 36b) a značka Koniec miestnej časti obce (č. IS 36d) informujú o skončení obce alebo časti obce z hľadiska platnosti ustanovení pravidiel cestnej premávky, ktoré sa vzťahujú na pravidlá správania sa v obci. Značka č. IS 36b končí platnosť značky č. IS 36a; ak platnosť značky č. IS 36c nebola skôr skončená značkou č. IS 36d, značka č. IS 36b končí platnosť značky č. IS 36c. Značka č. IS 36d končí platnosť značky č. IS 36c; ak platnosť značky č. IS 36a nebola skôr skončená značkou č. IS 36b, značka č. IS 36d končí platnosť značky č. IS 36a. Značky č. IS 36b a č. IS 36d končia platnosť značky č. B 31a, ak nie je skôr skončená inak; značky možno použiť samostatne alebo ich kombinovať.');
INSERT INTO `RoadSigns` VALUES (291,'IS','IS37a','Označenie začiatku obce v jazyku maďarskej menšiny','is37a','Značka Označenie začiatku obce v jazyku národnostnej menšiny (č. IS 37a) a značka Označenie konca obce v jazyku národnostnej menšiny (č. IS 37b) informatívne označujú začiatok a koniec obce v jazyku národnostnej menšiny.');
INSERT INTO `RoadSigns` VALUES (292,'IS','IS37b','Označenie koniec obce v jazyku maďarskej menšiny','is37b','Značka Označenie začiatku obce v jazyku národnostnej menšiny (č. IS 37a) a značka Označenie konca obce v jazyku národnostnej menšiny (č. IS 37b) informatívne označujú začiatok a koniec obce v jazyku národnostnej menšiny.');
INSERT INTO `RoadSigns` VALUES (293,'IS','IS38','Hraničný priechod','is38','Značka Hraničný priechod (č. IS 38) informuje o prístupe k hraničnému priechodu s názvom susedného štátu a o vzdialenosti k nemu; ak ide o členský štát Európskej únie, na modrú plochu okolo názvu štátu sa vyznačí 12 žltých hviezdičiek.');
INSERT INTO `RoadSigns` VALUES (294,'IS','IS39','Hranica štátu','is39','Značka Hranica štátu (č. IS 39) vyznačuje miesto vstupu do susedného štátu s názvom štátu a hranicu medzi nimi; ak ide o členský štát Európskej únie, na modrú plochu okolo názvu štátu sa vyznačí 12 žltých hviezdičiek.');
INSERT INTO `RoadSigns` VALUES (295,'IS','IS4','Návesť pred križovatkou','is4','Značka Návesť pred križovatkou (č. IS 4) informuje na diaľnici a rýchlostnej ceste o cieľoch v priamom smere, čísle pokračujúcej cesty, počte a usporiadaní jazdných pruhov v priamom smere. Pre farebné vyhotovenie a spôsob uvádzania cieľov a čísel ciest platia podmienky ako pri značke č. IS 2.');
INSERT INTO `RoadSigns` VALUES (296,'IS','IS40a','Smerová tabuľa pre cyklistov (s jedným cieľom)','is40a','');
INSERT INTO `RoadSigns` VALUES (297,'IS','IS40b','Smerová tabuľa pre cyklistov (s dvoma cieľmi)','is40b','');
INSERT INTO `RoadSigns` VALUES (298,'IS','IS40c','Smerová tabuľa pre cyklistov (s jedným cieľom)','is40c','');
INSERT INTO `RoadSigns` VALUES (299,'IS','IS40d','Smerová tabuľa pre cyklistov (s dvoma cieľmi)','is40d','');
INSERT INTO `RoadSigns` VALUES (300,'IS','IS40e','Návesť pred križovatkou pre cyklistov','is40e','');
INSERT INTO `RoadSigns` VALUES (301,'IS','IS40f','Smerová tabuľa pre cyklistov','is40f','');
INSERT INTO `RoadSigns` VALUES (302,'IS','IS40g','Smerová tabuľa pre cyklistov','is40g','');
INSERT INTO `RoadSigns` VALUES (303,'IS','IS40h','Smerová tabuľa pre cyklistov','is40h','');
INSERT INTO `RoadSigns` VALUES (304,'IS','IS40i','Koniec cyklistickej trasy','is40i','');
INSERT INTO `RoadSigns` VALUES (305,'IS','IS5a','Návesť pred križovatkou','is5a','Značky Návesť pred križovatkou (č. IS 5a a 5b) informujú na diaľnici a rýchlostnej ceste o cieľoch, počte a usporiadaní jazdných pruhov v smere odbočenia. Pre farebné vyhotovenie a spôsob uvádzania cieľov a čísel ciest platia podmienky ako pri značke č. IS 2.');
INSERT INTO `RoadSigns` VALUES (306,'IS','IS5b','Návesť pred križovatkou','is5b','Značky Návesť pred križovatkou (č. IS 5a a 5b) informujú na diaľnici a rýchlostnej ceste o cieľoch, počte a usporiadaní jazdných pruhov v smere odbočenia. Pre farebné vyhotovenie a spôsob uvádzania cieľov a čísel ciest platia podmienky ako pri značke č. IS 2.');
INSERT INTO `RoadSigns` VALUES (307,'IS','IS6','Návesť pred križovatkou','is6','Značka Návesť pred križovatkou (č. IS 6) poskytuje na diaľnici a rýchlostnej ceste rozšírené informácie o cieľoch v smere odbočenia. V hornej časti značky je uvedený názov a označenie križovatky. Pod označením križovatky môžu byť na subplochách uvedené aj ďalšie dostupné ciele. Pre farebné vyhotovenie a spôsob uvádzania cieľov a čísel ciest platia podmienky ako pri značke č. IS 2. Ak je na značke uvedený kultúrny alebo turistický cieľ, farba subplochy je hnedá.');
INSERT INTO `RoadSigns` VALUES (308,'IS','IS7a','Smerová tabuľa','is7a','Značka Smerová tabuľa (č. IS 7a) informuje o cieli (cieľoch) v smere odbočenia a čísle križujúcej diaľnice, rýchlostnej cesty a cesty. Pre farebné vyhotovenie a spôsob uvádzania cieľov a čísel ciest platia podmienky ako pri značke č. IS 9.');
INSERT INTO `RoadSigns` VALUES (309,'IS','IS7b','Výjazd','is7b','Značka Výjazd (č. IS 7b) informuje na diaľnici a rýchlostnej ceste o čísle výjazdu (odbočenia) na inú cestu, ktoré zodpovedá staničeniu križovatky. Používa sa v križovatkách označených značkou č. IS 1b okrem križovatiek s viacerými výjazdovými vetvami. Pre farebné vyhotovenie a spôsob uvádzania platia podmienky ako pri značke č. IS 2.');
INSERT INTO `RoadSigns` VALUES (310,'IS','IS8','Diaľková návesť','is8','Značka Diaľková návesť (č. IS 8) informuje o cieľoch a vzdialenosti k vyznačeným cieľom v kilometroch. Pre farebné vyhotovenie a spôsob uvádzania cieľov a čísel diaľnic, rýchlostných ciest a ciest platia podmienky ako pri značke č. IS 2.');
INSERT INTO `RoadSigns` VALUES (311,'IS','IS9','Návesť pred križovatkou','is9','Značka Návesť pred križovatkou (IS 9) informuje o smere k vyznačeným cieľom z najbližšej križovatky, prípadne aj o vzdialenosti k nej. Schematicky znázorňuje vedenie hlavnej a vedľajšej cesty. Značka sa používa pred dopravne významnými križovatkami ciest I., II. a III. triedy a pred dôležitými cestami v obci. Základná plocha značky na ceste I., II. a III. triedy je vždy modrej farby; ak sa cieľ nachádza na výjazde smerom na diaľnicu alebo na rýchlostnú cestu, uvedie sa na základnej modrej ploche subplocha zelenej farby s uvedením názvu cieľa, a ak sa ako cieľ uvádza na miestnych cestách na návestenie miestnych a iných cieľov, uvedie sa na základnej modrej ploche subplocha bielej farby. Na bielej subploche sú nápisy a šípky (symboly) čierne. Spravidla sa k uvedenému cieľu na značke uvedie aj označenie cesty. Ak sú ciele dostupné po obchádzkovej alebo odklonovej trase, možno ich vyznačiť na žltej subploche alebo ploche.');
INSERT INTO `RoadSigns` VALUES (312,'O','O1','Označenie vozidla vedeného osobou sluchovo postihnutou','o1','Osobitné označenie vozidla vedeného osobou so sluchovým postihnutím (č. O 1) označuje vozidlo vedené osobou so sluchovým postihnutím v čase použitia vozidla touto osobou.');
INSERT INTO `RoadSigns` VALUES (313,'O','O2','Označenie vozidla lekára pri poskytovaní zdravotnej starostlivosti','o2','Označenie vozidla lekára pri poskytovaní zdravotnej starostlivosti (č. O 2) označuje vozidlo používané lekárom pri poskytovaní zdravotnej starostlivosti v čase použitia vozidla na tieto účely. V dolnej časti označenia č. O 2 je uvedené šesťmiestne proporcionálne a výškovo zväčšované číslo prináležiace k osobitnému označeniu, ktoré je zhodné s číslom preukazu osobitného označenia vozidla vydaného príslušným obvodným úradom v sídle kraja.');
INSERT INTO `RoadSigns` VALUES (314,'O','O3','Označenie autobusu prepravujúceho deti','o3','Osobitné označenie autobusu prepravujúceho deti (č. O 3) označuje autobus používaný na prepravu detí v čase použitia autobusu na tieto účely.');
INSERT INTO `RoadSigns` VALUES (315,'O','O4','Označenie vozidla vedeného vodičom začiatočníkom','o4','Osobitné označenie vozidla vedeného vodičom začiatočníkom (č. O 4) označuje vozidlo vedené vodičom začiatočníkom.');
INSERT INTO `RoadSigns` VALUES (316,'P','P1','Daj prednosť v jazde','p1','Značka Daj prednosť v jazde! (č. P 1) ukladá vodičovi povinnosť dať prednosť v jazde; označuje vedľajšiu cestu pred križovatkou s hlavnou cestou. Značka sa používa najmä v kombinácii s príslušnou dodatkovou tabuľkou s tvarom križovatky Tvar križovatky č. P 13 až P 15.');
INSERT INTO `RoadSigns` VALUES (317,'P','P10','Prednosť protiidúcich vozidiel','p10','Značka Prednosť protiidúcich vozidiel (č. P 10) označuje úsek cesty, kde nie je možná obojsmerná premávka s dostatočným bočným odstupom protiidúcich vozidiel a kde platí prednosť v jazde protiidúcich vozidiel. Z opačnej strany zúženého úseku sa umiestňuje značka č. P 11.');
INSERT INTO `RoadSigns` VALUES (318,'P','P11','Prednosť pred protiidúcimi vozidlami','p11','Značka Prednosť pred protiidúcimi vozidlami (č. P 11) označuje úsek cesty, kde nie je možná obojsmerná premávka s dodatočným bočným odstupom protiidúcich vozidiel a kde platí prednosť v jazde pred protiidúcimi vozidlami. Z opačnej strany zúženého úseku sa umiestňuje značka č. P 10.');
INSERT INTO `RoadSigns` VALUES (319,'P','P12','Tvar križovatky (vzor)','p12','Dodatkové tabuľky Tvar križovatky (č. P 12 až P 14) a Tvar dvoch križovatiek (č. P 15) vyznačujú skutočný geometrický tvar križovatky, pričom hlavná cesta je vyznačená čiarou dvojnásobnej šírky ako čiara vyznačujúca vedľajšie cesty, okrem dodatkovej tabuľky Tvar križovatky (č. P 12), ktorá vyznačuje len cesty rovnakého významu. Cesta, po ktorej sa ku križovatke prichádza, je vyznačená čiarou vychádzajúcou od spodného okraja dodatkovej tabuľky s tvarom križovatky v smere jazdy vodiča.');
INSERT INTO `RoadSigns` VALUES (320,'P','P13','Tvar križovatky (vzor)','p13','Dodatkové tabuľky Tvar križovatky (č. P 12 až P 14) a Tvar dvoch križovatiek (č. P 15) vyznačujú skutočný geometrický tvar križovatky, pričom hlavná cesta je vyznačená čiarou dvojnásobnej šírky ako čiara vyznačujúca vedľajšie cesty, okrem dodatkovej tabuľky Tvar križovatky (č. P 12), ktorá vyznačuje len cesty rovnakého významu. Cesta, po ktorej sa ku križovatke prichádza, je vyznačená čiarou vychádzajúcou od spodného okraja dodatkovej tabuľky s tvarom križovatky v smere jazdy vodiča.');
INSERT INTO `RoadSigns` VALUES (321,'P','P14','Tvar križovatky (vzor)','p14','Dodatkové tabuľky Tvar križovatky (č. P 12 až P 14) a Tvar dvoch križovatiek (č. P 15) vyznačujú skutočný geometrický tvar križovatky, pričom hlavná cesta je vyznačená čiarou dvojnásobnej šírky ako čiara vyznačujúca vedľajšie cesty, okrem dodatkovej tabuľky Tvar križovatky (č. P 12), ktorá vyznačuje len cesty rovnakého významu. Cesta, po ktorej sa ku križovatke prichádza, je vyznačená čiarou vychádzajúcou od spodného okraja dodatkovej tabuľky s tvarom križovatky v smere jazdy vodiča.');
INSERT INTO `RoadSigns` VALUES (322,'P','P15','Tvar križovatky (vzor)','p15','Dodatkové tabuľky Tvar križovatky (č. P 12 až P 14) a Tvar dvoch križovatiek (č. P 15) vyznačujú skutočný geometrický tvar križovatky, pričom hlavná cesta je vyznačená čiarou dvojnásobnej šírky ako čiara vyznačujúca vedľajšie cesty, okrem dodatkovej tabuľky Tvar križovatky (č. P 12), ktorá vyznačuje len cesty rovnakého významu. Cesta, po ktorej sa ku križovatke prichádza, je vyznačená čiarou vychádzajúcou od spodného okraja dodatkovej tabuľky s tvarom križovatky v smere jazdy vodiča.');
INSERT INTO `RoadSigns` VALUES (323,'P','P2','Stoj, daj prednosť v jazde','p2','Značka Stoj, daj prednosť v jazde! (č. P 2) ukladá vodičovi povinnosť zastaviť vozidlo a dať prednosť v jazde; vodič je povinný zastaviť vozidlo na takom mieste, odkiaľ má na križovatku náležitý rozhľad. Značka označuje vedľajšiu cestu pred križovatkou s hlavnou cestou, a to najmä v prípadoch, keď križovatka nie je dostatočne prehľadná; za predpokladu, že miesto na zastavenie vozidla je možné presne vymedziť, použije sa značka v kombinácii so značkou č. V 5c. Značka č. P 2 sa používa najmä v kombinácii s príslušnou dodatkovou tabuľkou s tvarom križovatky Tvar križovatky č. P 13 až P 15. Ako predbežná značka sa k značke č. P 2 používa značka č. P 1 s dodatkovou tabuľkou č. E 2 s uvedením skutočnej vzdialenosti k miestu, na ktoré sa vzťahuje povinnosť zastaviť vozidlo; na uvedenie tejto skutočnej vzdialenosti možno použiť i značku č. V 14. Značka č. P 2 sa používa aj pred železničným priecestím v prípadoch, keď je potrebné vodičovi prikázať v záujme bezpečnosti premávky zastaviť vozidlo.');
INSERT INTO `RoadSigns` VALUES (324,'P','P3','Daj prednosť v jazde električke','p3','Značka Daj prednosť v jazde električke! (č. P 3) sa používa na mieste, kde v sporných alebo iných prípadoch treba prikázať vodičovi dať prednosť v jazde električke, alebo na zdôraznenie inak určenej povinnosti dať prednosť v jazde električke. Značka č. P 3 sa umiestňuje pred miestom priblíženia električkovej koľaje k okraju vozovky, napríklad na znemožnenie jazdy vozidiel pozdĺž električky, a pred miestom, kde električka križuje smer jazdy ostatných vozidiel.');
INSERT INTO `RoadSigns` VALUES (325,'P','P4','Križovatka','p4','Značka Križovatka (č. P 4) upozorňuje na križovatku, kde nie je prednosť v jazde upravená značkami napríklad na upozornenie na križovatku, kde sa na rozdiel od predchádzajúceho priebehu končí hlavná cesta a uplatňuje sa ustanovenie vyplývajúce zo všeobecných ustanovení pravidiel cestnej premávky „prednosť vozidiel prichádzajúcich sprava“.');
INSERT INTO `RoadSigns` VALUES (326,'P','P5','Križovatka s vedľajšou cestou','p5','Značka Križovatka s vedľajšou cestou (č. P 5) sa používa mimo obce a upozorňuje na križovatku s vedľajšou cestou a označuje hlavnú cestu. Značka Križovatka s vedľajšou cestou (č. P 6) sa taktiež používa mimo obce a možno ju použiť namiesto značky č. P 5, pričom upozorňuje na križovatku s vedľajšou cestou pripojenou sprava pod určitým stupňom a označuje hlavnú cestu; na označenie hlavnej cesty s vedľajšou cestou zľava je jej symbol obrátený.');
INSERT INTO `RoadSigns` VALUES (327,'P','P6','Križovatka s vedľajšou cestou (vzor)','p6','Značka Križovatka s vedľajšou cestou (č. P 5) sa používa mimo obce a upozorňuje na križovatku s vedľajšou cestou a označuje hlavnú cestu. Značka Križovatka s vedľajšou cestou (č. P 6) sa taktiež používa mimo obce a možno ju použiť namiesto značky č. P 5, pričom upozorňuje na križovatku s vedľajšou cestou pripojenou sprava pod určitým stupňom a označuje hlavnú cestu; na označenie hlavnej cesty s vedľajšou cestou zľava je jej symbol obrátený.');
INSERT INTO `RoadSigns` VALUES (328,'P','P7','Okružná križovatka','p7','Značka Križovatka s kruhovým objazdom (č. P 7) upozorňuje vopred ako značka predbežná na kruhový objazd, ktorý je označený značkou Kruhový objazd (č. C 7).');
INSERT INTO `RoadSigns` VALUES (329,'P','P8','Hlavná cesta','p8','Značka Hlavná cesta (č. P 8) upozorňuje najmä v obci na križovatku s vedľajšou cestou a označuje hlavnú cestu. Používa sa v kombinácii najmä s príslušnou dodatkovou tabuľkou s tvarom križovatky Tvar križovatky č. P 13 až P 15.');
INSERT INTO `RoadSigns` VALUES (330,'P','P9','Koniec hlavnej cesty','p9','Značka Koniec hlavnej cesty (č. P 9) informuje o tom, že na najbližšej križovatke táto cesta už nie je hlavnou cestou. V obci sa značka č. P 9 používa len pred skončením dlhšieho úseku hlavnej cesty, a to za poslednou križovatkou hlavnej cesty.');
