INSERT INTO `RoadSigns` VALUES (386,'V','V10a','Parkovacie miesta s kolmým státím','v10a','Značky Parkovacie miesta s kolmým státím, (č. V 10a), Parkovacie miesta so šikmým státím (č. V 10b) a Parkovacie miesta s pozdĺžnym státím (č. V 10c) vyznačujú miesto, kde je dovolené zastavenie a státie a určený spôsob státia.');
INSERT INTO `RoadSigns` VALUES (387,'V','V10b','Parkovacie miesta so šikmým státím','v10b','Značky Parkovacie miesta s kolmým státím, (č. V 10a), Parkovacie miesta so šikmým státím (č. V 10b) a Parkovacie miesta s pozdĺžnym státím (č. V 10c) vyznačujú miesto, kde je dovolené zastavenie a státie a určený spôsob státia.');
INSERT INTO `RoadSigns` VALUES (388,'V','V10c','Parkovacie miesta s pozdĺžnym státím','v10c','Značky Parkovacie miesta s kolmým státím, (č. V 10a), Parkovacie miesta so šikmým státím (č. V 10b) a Parkovacie miesta s pozdĺžnym státím (č. V 10c) vyznačujú miesto, kde je dovolené zastavenie a státie a určený spôsob státia.');
INSERT INTO `RoadSigns` VALUES (389,'V','V10d','Parkovacie miesta s vyhradeným státím','v10d','Značka Parkovacie miesta s vyhradeným státím (č. V 10d) s príslušným vhodným nápisom alebo symbolom vyznaču- je priestor parkovacieho miesta s vyhradeným státím a dopĺňa značku č. IP 16.');
INSERT INTO `RoadSigns` VALUES (390,'V','V10e','Stanovište TAXI','v10e','Značka Stanovište TAXI (č. V 10e) s príslušným nápisom TAXI vyznačuje priestor stanovišťa taxi a dopĺňa značku č. IP 20b.');
INSERT INTO `RoadSigns` VALUES (391,'V','V11a','Zastávka autobusu, trolejbusu a električky','v11a','Značka Zastávka autobusu, trolejbusu alebo električky (č. V 11b) s nápisom BUS alebo TRAM pre zastávku električky vyznačuje priestor zastávky uvedených vozidiel. Značka sa používa na zdôraznenie umiestnenia zastávky alebo na vyznačenie zastávky. Značku č. V 11b možno použiť aj v bielej farbe.');
INSERT INTO `RoadSigns` VALUES (392,'V','V11b','Varovný pás od zastávky autobusu, trolejbusu a električky','v11b','Značka Varovný pás od zástavky autobusu, trolejbusu a električky (č. V 11b) upozorňuje z dôvodu bezpečnosti osôb na zástavkách pravidelnej verejnej dopravy osôb na bezpečnú vzdialenosť od priľahlej vozovky. Značka vyznačuje bezpečnostný priestor nástupišťa zastávky, do ktorého je zakázané osobám vstupovať alebo doň inak presahovať v čase príjazdu vozidla pravidelnej verejnej dopravy osôb do priestoru zástavky, a to až do jeho zastavenia; ako varov- ný pás možno použiť aj varovný pás pre nevidiacich č. Z 8b v červenej farbe.');
INSERT INTO `RoadSigns` VALUES (393,'V','V12a','Žltá kľukatá čiara','v12a','Značka Žltá kľukatá čiara (č. V 12a) vyznačuje priestor, kde je zakázané státie vozidiel.');
INSERT INTO `RoadSigns` VALUES (394,'V','V12b','Žltá súvislá čiara','v12b','Značka Žltá súvislá čiara (č. V 12b) vyznačuje úsek, kde je z obidvoch strán tejto čiary zakázané zastavenie a státie vozidiel.');
INSERT INTO `RoadSigns` VALUES (395,'V','V12c','Žltá prerušovaná čiara','v12c','Značka Žltá prerušovaná čiara (č. V 12c) vyznačuje úsek, kde je z obidvoch strán tejto čiary zakázané státie vozidiel.');
INSERT INTO `RoadSigns` VALUES (396,'V','V13','Šikmé rovnobežné čiary','v13','Značka Šikmé rovnobežné čiary (č. V 13) vyznačuje priestor, do ktorého je zakázané vchádzať alebo doň nákladom presahovať, ak to nie je potrebné na obchádzanie, odbočovanie na miesto mimo cesty alebo na poľnú cestu, lesnú cestu, cestičku pre cyklistov alebo do obytnej zóny, alebo do pešej zóny, pričom nesmú byť ohrození ostatní účastníci cestnej premávky.');
INSERT INTO `RoadSigns` VALUES (397,'V','V14','Nápisy na vozovke','v14','Značka Nápisy na ceste (č. V 14) sa používa na povrchu cesty, parkoviska alebo na inej dopravnej ploche a vhodným údajom alebo nápismi napríklad BUS, TRAM, TIR, NITRA, STOP a podobne vyjadruje rôzne doplňujúce údaje.');
INSERT INTO `RoadSigns` VALUES (398,'V','V15','Bezpečná vzdialenosť','v15','Značka Bezpečná vzdialenosť (č. V 15) vyznačuje na ceste pozorovacie body, ktoré v spojení so značkou č. IP 32 odporúčajú vzdialenosť pre vozidlá idúce za sebou pri priaznivých dopravných a poveternostných podmienkach; bezpečná vzdialenosť je zobrazená na značke č. IP 32.');
INSERT INTO `RoadSigns` VALUES (399,'V','V16','Optická psychologická brzda','v16','Značka Optická psychologická brzda (č. V 16) opticky, prípadne aj zvukovo vedie vodičov k zníženiu rýchlosti jazdy pred miestom, na ktorom hrozí nebezpečenstvo a je potrebné zvýšiť opatrnosť.');
INSERT INTO `RoadSigns` VALUES (400,'V','V17','Hmlové body','v17','Značka Hmlové body (č. V 17) vyznačuje na ceste pozorovacie body, ktoré v spojení so značkami č. IP 31a až IP 31c „odporúčajú rýchlosť v kilometroch za hodinu“ za zníženej viditeľnosti, najmä pri výskyte hmly alebo dymu.');
INSERT INTO `RoadSigns` VALUES (401,'V','V1a','Pozdĺžna súvislá čiara','v1a','Značka Pozdĺžna súvislá čiara (č. V 1a) sa používa na oddelenie jazdných pruhov s protismernou premávkou a na od- delenie radiacich pruhov pred križovatkou. Vodič musí ísť vpravo od tejto značky. Značku je zakázané prechádzať alebo nákladom presahovať, ak to nie je potrebné na obchádzanie alebo odbočovanie na miesto mimo cesty alebo na vchádzanie z miesta mimo cesty na cestu.');
INSERT INTO `RoadSigns` VALUES (402,'V','V1b','Dvojitá pozdĺžna súvislá čiara','v1b','Značka Dvojitá pozdĺžna súvislá čiara (č. V 1b) sa používa na oddelenie protismernej premávky dvomi alebo viacerý- mi jazdnými pruhmi. Značka sa používa podľa rovnakých zásad ako značka č. V 1a.');
INSERT INTO `RoadSigns` VALUES (403,'V','V2a','Pozdĺžna prerušovaná čiara','v2a','Značky Pozdĺžna prerušovaná čiara (č. V 2a a č. V 2b) sa môžu prechádzať pri dodržaní ostatných ustanovení tejto vyhlášky. Značka č. V 2a s rozostupmi (medzerami) dvojnásobnej až štvornásobnej dĺžky, ako je dĺžka úsečiek vrátane odbočovacích a pripájacích pruhov, vyznačuje najmä jazdné pruhy. Značka č. V 2b s úsečkami rovnakej až štvornásobnej dĺžky, ako je dĺžka medzier, vyznačuje jazdné pruhy a predchádza značke č. V 1a alebo upozorňuje na nebezpečné miesta (zákrutu, križovatku a podobne); značka môže byť doplnená značkou Predbežné šípky č. V 9b.');
INSERT INTO `RoadSigns` VALUES (404,'V','V2b','Pozdĺžna prerušovaná čiara','v2b','Značky Pozdĺžna prerušovaná čiara (č. V 2a a č. V 2b) sa môžu prechádzať pri dodržaní ostatných ustanovení tejto vyhlášky. Značka č. V 2a s rozostupmi (medzerami) dvojnásobnej až štvornásobnej dĺžky, ako je dĺžka úsečiek vrátane odbočovacích a pripájacích pruhov, vyznačuje najmä jazdné pruhy. Značka č. V 2b s úsečkami rovnakej až štvornásobnej dĺžky, ako je dĺžka medzier, vyznačuje jazdné pruhy a predchádza značke č. V 1a alebo upozorňuje na nebezpečné miesta (zákrutu, križovatku a podobne); značka môže byť doplnená značkou Predbežné šípky č. V 9b.');
INSERT INTO `RoadSigns` VALUES (405,'V','V2c','Dvojitá pozdĺžna prerušovaná čiara','v2c','Značka Dvojitá pozdĺžna prerušovaná čiara (č. V 2c) vyznačuje jazdný pruh používaný striedavo pre jeden aj druhý smer jazdy; ak sa jazdný pruh takto nepoužíva, má značka Dvojitá pozdĺžna prerušovaná čiara č. V 2c rovnaký význam ako značky č. V 2a alebo č. V 2b.');
INSERT INTO `RoadSigns` VALUES (406,'V','V3','Pozdĺžna súvislá čiara doplnená prerušovanou čiarou','v3','Ak sú značkou Pozdĺžna súvislá čiara doplnená prerušovanou čiarou (č. V 3) oddelené jazdné pruhy s protismernou premávkou, vodič sa riadi významom pravej čiary z tejto dvojice čiar. Ak sú touto značkou vyznačené jazdné pruhy v jednom smere jazdy, vodič sa riadi významom bližšej čiary.');
INSERT INTO `RoadSigns` VALUES (407,'V','V4','Vodiaca čiara','v4','Značka Vodiaca čiara (č. V 4) vyznačuje okraj vozovky a oddeľuje vozovku od krajnice, prípadne chodníka. Vyhotovenie prerušovanej a plnej čiary možno použiť aj na oddelenie časti odbočovacieho alebo pripájacieho pruhu od priebežného pruhu. Vyhotovenie prerušovanej čiary sa používa najmä pri vyústení vjazdu z miesta mimo cesty a na oddelenie vjazdového alebo výjazdového klina zastávkového pruhu a na oddelenie parkovacieho pruhu. Značka č. V 4 neupravuje prednosť v jazde!');
INSERT INTO `RoadSigns` VALUES (408,'V','V5a','Priečna súvislá čiara','v5a','Značky Priečna súvislá čiara (č. V 5a), Priečna súvislá čiara so symbolom „Daj prednosť v jazde!“ (č. V 5b) a Priečna súvislá čiara s nápisom „STOP“ (č. V 5c) vyznačujú hranicu križovatky; to neplatí, ak sa tieto značky použijú ako po- mocné čiary na zastavenie vozidla v priestore križovatky. Značka (č. V 5c) vyznačuje miesto, kde je vodič povinný za- staviť vozidlo na príkaz značky č. P 2.');
INSERT INTO `RoadSigns` VALUES (409,'V','V5b','"Priečna súvislá čiara so symbolom ""Daj prednos v jazde!"""','v5b','Značky Priečna súvislá čiara (č. V 5a), Priečna súvislá čiara so symbolom „Daj prednosť v jazde!“ (č. V 5b) a Priečna súvislá čiara s nápisom „STOP“ (č. V 5c) vyznačujú hranicu križovatky; to neplatí, ak sa tieto značky použijú ako po- mocné čiary na zastavenie vozidla v priestore križovatky. Značka (č. V 5c) vyznačuje miesto, kde je vodič povinný za- staviť vozidlo na príkaz značky č. P 2.');
INSERT INTO `RoadSigns` VALUES (410,'V','V5c','"Priečna súvislá čiara s nápisom ""STOP"""','v5c','Značky Priečna súvislá čiara (č. V 5a), Priečna súvislá čiara so symbolom „Daj prednosť v jazde!“ (č. V 5b) a Priečna súvislá čiara s nápisom „STOP“ (č. V 5c) vyznačujú hranicu križovatky; to neplatí, ak sa tieto značky použijú ako po- mocné čiary na zastavenie vozidla v priestore križovatky. Značka (č. V 5c) vyznačuje miesto, kde je vodič povinný za- staviť vozidlo na príkaz značky č. P 2.');
INSERT INTO `RoadSigns` VALUES (411,'V','V5d','Priestor pre cyklistov','v5d','');
INSERT INTO `RoadSigns` VALUES (412,'V','V6a','Priechod pre chodcov','v6a','Značka Priechod pre chodcov (č. V 6a) vyznačuje plochu, na ktorú sa usmerňuje prechod chodcov cez vozovku a kto- rou sa zabezpečuje prednosť pešej premávky pred premávkou vozidiel. Na zvýraznenie viditeľnosti možno značku č. V 6a aplikovať v retroreflexnom červenobielom farebnom vyhotovení, pričom červená farebná úprava musí presahovať biele pruhy po stranách v smere jazdy vozidiel o 50 cm. Zásady použitia značky č. V 6a sú rovnaké ako zásady použitia značky č. IP 6.');
INSERT INTO `RoadSigns` VALUES (413,'V','V6b','Priechod pre chodcov s vodiacim pásom pre nevidiacich','v6b','Značka Priechod pre chodcov s vodiacim pásom pre nevidiacich (č. V 6b) vyznačuje plochu, na ktorú sa usmerňuje prechod chodcov cez vozovku a ktorou sa zabezpečuje prednosť pešej premávky pred premávkou vozidiel, pričom značka č. V 6b je použitá v kombinácii so zariadením č. Z 8a. Vodiaci pás zariadenia č. Z 8a musí vždy bezprostredne nadväzovať na varovný pás zariadenia č. Z 8b a smerovým vedením zodpovedať signálnemu pásu zariadenia č. Z 8c, ktorý je umiestnený v priľahlom chodníku; inak značka č. V 6b sa nepoužije. Značka č. V 6b má rovnaký význam ako značka č. V 6a a používa sa vždy podľa rovnakých zásad.');
INSERT INTO `RoadSigns` VALUES (414,'V','V7','Priechod pre cyklistov','v7','Značka Priechod pre cyklistov (č. V 7) vyznačuje kríženie cyklistickej cestičky s vozovkou. Na prejazd cyklistov sa vopred upozorňuje značkou č. A 16.');
INSERT INTO `RoadSigns` VALUES (415,'V','V7a','Priechod pre cyklistov primknutý k priechodu pre chodcov','v7a','');
INSERT INTO `RoadSigns` VALUES (416,'V','V8a','Cyklistická smerová šípka','v8a','Značka Cyklistická smerová šípka (č. V 8a a č. V 8b) vyznačuje na cestičke pre cyklistov určený smer jazdy cyklistov; spolu s pozdĺžnymi čiarami dopĺňa značku č. C 8.');
INSERT INTO `RoadSigns` VALUES (417,'V','V8b','Cyklistická smerová šípka','v8b','Značka Cyklistická smerová šípka (č. V 8a a č. V 8b) vyznačuje na cestičke pre cyklistov určený smer jazdy cyklistov; spolu s pozdĺžnymi čiarami dopĺňa značku č. C 8.');
INSERT INTO `RoadSigns` VALUES (418,'V','V8c','Koridor pre cyklistov','v8c','');
INSERT INTO `RoadSigns` VALUES (419,'V','V9a','Smerové šípky','v9a','Značka Smerové šípky (č. V 9a) vyznačuje spôsob radenia do jazdných pruhov, určený smer jazdy križovatkou a zodpovedá skutočnej dopravnej situácii na ceste; značkou č. V 9a možno vyznačiť, kde platí značkou č. C 25 povolené otáčanie vozidiel v priestore riadenej križovatky.');
INSERT INTO `RoadSigns` VALUES (420,'V','V9b','Predbežné šípky','v9b','Značka Predbežné šípky (č. V 9b) vyznačuje blížiaci sa prechod pozdĺžnej prerušovanej čiary na súvislú čiaru; ak je umiestnená v osi jazdného pruhu, vyznačuje jeho blížiace sa skončenie.');
INSERT INTO `RoadSigns` VALUES (421,'Z','Z1','Dopravný kužeľ','z1','Dopravné kužele (č. Z 1) umiestnené v rade za sebou majú zhodný význam ako značka č. V 1a, a to aj vtedy, ak sú umiestnené na značkách č. V 2a, č. V 2b, č. V 2c alebo č. V 3. Môžu vymedzovať priestor, do ktorého je zakázané vchádzať.');
INSERT INTO `RoadSigns` VALUES (434,'Z','Z2a','Zábrana na označenie uzávierky','z2a','Zábrana na označenie uzávierky (č. Z 2a) vyznačuje uzávierku celej šírky cesty.');
INSERT INTO `RoadSigns` VALUES (435,'Z','Z2b','Zábrana na označenie uzávierky','z2b','Zábrana na označenie uzávierky (č. Z 2b) vyznačuje uzavretie časti šírky cesty; šípky smerujú k voľnej časti cesty.');
INSERT INTO `RoadSigns` VALUES (436,'Z','Z2c','Žlté a čierne pruhy','z2c','Žlté a čierne pruhy (č. Z 2c) označujú trvalú prekážku (pilier, stenu a podobne).');
INSERT INTO `RoadSigns` VALUES (438,'Z','Z3a','Vodiaca tabuľa','z3a','Vodiace tabule (č. Z 3a a č. Z 3b) usmerňujú premávku v smere šípok a označujú najmä nebezpečnú zákrutu. V odôvodnených prípadoch môže byť biela farba zariadení č. Z 3a a č. Z 3b nahradená retroreflexnou žltozelenou fluorescenčnou farbou.');
INSERT INTO `RoadSigns` VALUES (448,'Z','Z5c','Smerovka','z5c','Smerovka (č. Z 5c) sa používa pri riadení premávky na križovatke najmä príslušníkom Policajného zboru v rovnošate, ale taktiež vojenským policajtom, vojakom pri plnení úloh ozbrojených síl Slovenskej republiky.');
INSERT INTO `RoadSigns` VALUES (449,'Z','Z6a','Prefabrikovaný spomaľovací prah','z6a','Prefabrikovaný spomaľovací prah (č. Z 6a) je vyhotovený najmä z odnímateľného segmentu, ktorý sa používa na zníženie rýchlosti na danom úseku cesty náhlou zmenou jej výškového profilu, pričom každý segment musí byť opatrený retroreflexnými prvkami; možno ho použiť podľa grafického vyobrazenia iba v žlto-čiernom farebnom vyhotovení.');
